   void InputWorker::ProcessQueue() {
       while (running_) {
           auto evt = queue_.Pop(); // blocking pop
           INPUT input{};
           if (evt.type == InputType::MouseMove) {
               PrepareMouseMove(input, evt);
           } else if (evt.type == InputType::MouseButton) {
               PrepareMouseButton(input, evt);
           } else {
               PrepareKeyEvent(input, evt);
           }
           UINT sent = ::SendInput(1, &input, sizeof(INPUT));
           if (sent != 1) {
               LogError(::GetLastError());
           }
       }
   }
   ```

   - Run this worker on a separate thread so the network callbacks just push events into `queue_`.

4. **Modifiers**: If your protocol sends modifier state, ensure you also emit `SendInput` commands for Ctrl/Shift/Alt presses/releases as needed.

5. **Error handling**: If `SendInput` fails (common when not elevated or when foreground changes), retry a limited number of times or log + drop the event.

With this worker in place, the RemoteHost will faithfully simulate ControlLaptop’s keyboard/mouse actions, closing out Phase 3’s core requirement.

