#include "AppConfig.h"
#include <fstream>
#include <sstream>
#include <stdexcept>

namespace dialhome::config {
namespace {
std::unordered_map<std::string, std::string> ParseKeyValues(const std::filesystem::path& path) {
    std::ifstream file(path);
    if (!file) {
        throw std::runtime_error("Config file not found: " + path.string());
    }
    std::unordered_map<std::string, std::string> result;
    std::string line;
    while (std::getline(file, line)) {
        if (line.empty() || line[0] == '#') continue;
        auto pos = line.find('=');
        if (pos == std::string::npos) continue;
        auto key = line.substr(0, pos);
        auto value = line.substr(pos + 1);
        result[key] = value;
    }
    return result;
}
}

AppConfig AppConfig::Load(const std::filesystem::path& path) {
    AppConfig cfg;
    cfg.values_ = ParseKeyValues(path);
    return cfg;
}

const std::string& AppConfig::Get(const std::string& key) const {
    auto it = values_.find(key);
    if (it == values_.end()) {
        throw std::out_of_range("Missing config key: " + key);
    }
    return it->second;
}

bool AppConfig::Contains(const std::string& key) const {
    return values_.count(key) > 0;
}
}
