void TelemetryLogger::Write(const std::string& component, const std::string& eventJson) const {
    auto ts = std::chrono::system_clock::now();
    auto secs = std::chrono::time_point_cast<std::chrono::seconds>(ts);
    auto value = secs.time_since_epoch().count();
    std::ostringstream name;
    name << component << "-" << value << ".json";
    auto path = directory_ / name.str();
    std::ofstream file(path);
    if (!file) {
        throw std::runtime_error("Failed to open telemetry file: " + path.string());
    }
    file << eventJson;
}
}
