#include "ScreenCapture.h"
#include <stdexcept>

using Microsoft::WRL::ComPtr;

namespace dialhome::capture {
ScreenCapture::ScreenCapture() = default;
ScreenCapture::~ScreenCapture() { ReleaseFrame(); }

bool ScreenCapture::Initialize(UINT outputIndex) {
    outputIndex_ = outputIndex;
    UINT creationFlags = D3D11_CREATE_DEVICE_BGRA_SUPPORT;
#ifdef _DEBUG
    creationFlags |= D3D11_CREATE_DEVICE_DEBUG;
#endif
    D3D_FEATURE_LEVEL level = D3D_FEATURE_LEVEL_11_0;
    HRESULT hr = D3D11CreateDevice(nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr,
                                   creationFlags, &level, 1, D3D11_SDK_VERSION,
                                   &device_, nullptr, &context_);
    if (FAILED(hr)) {
        return false;
    }

    ComPtr<IDXGIDevice> dxgiDevice;
    hr = device_.As(&dxgiDevice);
    if (FAILED(hr)) return false;

    ComPtr<IDXGIAdapter> adapter;
    hr = dxgiDevice->GetAdapter(&adapter);
    if (FAILED(hr)) return false;

    ComPtr<IDXGIOutput> output;
    hr = adapter->EnumOutputs(outputIndex_, &output);
    if (FAILED(hr)) return false;

    ComPtr<IDXGIOutput1> output1;
    hr = output.As(&output1);
    if (FAILED(hr)) return false;

    hr = output1->DuplicateOutput(device_.Get(), &duplication_);
    if (FAILED(hr)) {
        duplication_.Reset();
        return false;
    }
    duplication_->GetDesc(&desc_);
    return true;
}

bool ScreenCapture::AcquireFrame(DXGI_OUTDUPL_FRAME_INFO& frameInfo,
                                 ComPtr<ID3D11Texture2D>& texture) {
    if (!duplication_) {
        return false;
    }
    ComPtr<IDXGIResource> resource;
    HRESULT hr = duplication_->AcquireNextFrame(16, &frameInfo, &resource);
    if (hr == DXGI_ERROR_WAIT_TIMEOUT) {
        return false;
    }
    if (FAILED(hr)) {
        ResetDuplication();
        return false;
    }
    hr = resource.As(&texture);
    if (FAILED(hr)) {
        duplication_->ReleaseFrame();
        return false;
    }
    frameAcquired_ = true;
    return true;
}

std::vector<RECT> ScreenCapture::GetDirtyRects() const {
    std::vector<RECT> rects;
    if (!duplication_ || !frameAcquired_) {
        return rects;
    }
    UINT required = 0;
    duplication_->GetFrameDirtyRects(0, nullptr, &required);
    if (required == 0) {
        return rects;
    }
    rects.resize(required / sizeof(RECT));
    duplication_->GetFrameDirtyRects(required, rects.data(), &required);
    return rects;
}

void ScreenCapture::ReleaseFrame() {
    if (duplication_ && frameAcquired_) {
        duplication_->ReleaseFrame();
        frameAcquired_ = false;
    }
}

void ScreenCapture::ResetDuplication() {
    ReleaseFrame();
    duplication_.Reset();
}
}
