namespace dialhome::ui {
BEGIN_MESSAGE_MAP(ViewportWnd, CStatic)
    ON_WM_PAINT()
END_MESSAGE_MAP()

ViewportWnd::ViewportWnd() {
    bmi_.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi_.bmiHeader.biPlanes = 1;
    bmi_.bmiHeader.biBitCount = 32;
    bmi_.bmiHeader.biCompression = BI_RGB;
}

void ViewportWnd::UpdateFrame(int width, int height) {
    width_ = width;
    height_ = height;
    bmi_.bmiHeader.biWidth = width_;
    bmi_.bmiHeader.biHeight = -height_; // top-down
    surface_.assign(width_ * height_ * 4, 0);
    Invalidate();
}

void ViewportWnd::BlitRect(const RECT& rect, const std::vector<uint8_t>& pixels) {
    if (width_ == 0 || height_ == 0) return;
    RECT clipped = rect;
    clipped.left = max(0, clipped.left);
    clipped.top = max(0, clipped.top);
    clipped.right = min(width_, clipped.right);
    clipped.bottom = min(height_, clipped.bottom);
    int rectWidth = clipped.right - clipped.left;
    int rectHeight = clipped.bottom - clipped.top;
    if (rectWidth <= 0 || rectHeight <= 0) return;

    const uint8_t* src = pixels.data();
    for (int y = 0; y < rectHeight; ++y) {
        size_t dstIndex = ((clipped.top + y) * width_ + clipped.left) * 4;
        memcpy(&surface_[dstIndex], src + (y * rectWidth * 4), rectWidth * 4);
    }
    InvalidateRect(&clipped, FALSE);
}

void ViewportWnd::OnPaint() {
    CPaintDC dc(this);
    if (width_ == 0 || height_ == 0 || surface_.empty()) {
        dc.FillSolidRect(CRect(0, 0, dc.m_ps.rcPaint.right, dc.m_ps.rcPaint.bottom), RGB(0, 0, 0));
        return;
    }
    SetDIBitsToDevice(dc.m_hDC,
                      0, 0,
                      width_, height_,
                      0, 0,
                      0, height_,
                      surface_.data(),
                      &bmi_,
                      DIB_RGB_COLORS);
}
}
