std::vector<uint8_t> FrameAssembler::Decompress(const std::vector<uint8_t>& data, size_t expectedBytes) {
    std::vector<uint8_t> output(expectedBytes);
    size_t decoded = ZSTD_decompressDCtx(ctx_, output.data(), output.size(), data.data(), data.size());
    if (ZSTD_isError(decoded)) {
        throw std::runtime_error(ZSTD_getErrorName(decoded));
    }
    output.resize(decoded);
    return output;
}

void FrameAssembler::ProcessFrame(const protocol::ScreenFrame& frame) {
    for (const auto& rect : frame.rects) {
        size_t expected = rect.width * rect.height * 4;
        auto pixels = Decompress(rect.data, expected);
        viewport_.BlitRect({rect.x, rect.y, rect.x + rect.width, rect.y + rect.height}, pixels);
    }
}
