INPUT MakeMouseInput(int x, int y, DWORD flags) {
    INPUT input{};
    input.type = INPUT_MOUSE;
    input.mi.dx = x;
    input.mi.dy = y;
    input.mi.dwFlags = flags;
    return input;
}
}

void InputExecutor::Submit(const protocol::InputEvent& event) {
    INPUT input{};
    if (event.type == protocol::InputType::MouseMove) {
        input = MakeMouseInput(event.x, event.y, MOUSEEVENTF_MOVE);
    } else if (event.type == protocol::InputType::MouseButton) {
        DWORD flag = (event.button == protocol::MouseButton::Left)
                         ? (event.pressed ? MOUSEEVENTF_LEFTDOWN : MOUSEEVENTF_LEFTUP)
                         : (event.pressed ? MOUSEEVENTF_RIGHTDOWN : MOUSEEVENTF_RIGHTUP);
        input = MakeMouseInput(event.x, event.y, flag);
    } else {
        input.type = INPUT_KEYBOARD;
        input.ki.wVk = static_cast<WORD>(event.keyCode);
        input.ki.dwFlags = event.pressed ? 0 : KEYEVENTF_KEYUP;
    }
    SendInput(1, &input, sizeof(INPUT));
}
}
