std::string ToIsoString(std::filesystem::file_time_type time) {
    auto sctp = std::chrono::time_point_cast<std::chrono::system_clock::duration>(time - decltype(time)::clock::now() + std::chrono::system_clock::now());
    std::time_t t = std::chrono::system_clock::to_time_t(sctp);
    std::tm tmStruct;
    gmtime_s(&tmStruct, &t);
    std::ostringstream oss;
    oss << std::put_time(&tmStruct, "%Y-%m-%dT%H:%M:%SZ");
    return oss.str();
}
}

std::vector<DirectoryEntry> DirectoryService::List(const std::filesystem::path& root) const {
    std::vector<DirectoryEntry> results;
    for (const auto& entry : std::filesystem::directory_iterator(root)) {
        DirectoryEntry rec;
        rec.name = entry.path().filename().u8string();
        rec.isDirectory = entry.is_directory();
        rec.size = rec.isDirectory ? 0 : entry.file_size();
        rec.modified = ToIsoString(entry.last_write_time());
        results.push_back(std::move(rec));
    }
    return results;
}
}
