            std::cerr << "[FileServer] io_context error: " << ex.what() << std::endl;
        }
    });
}

void FileServer::Stop() {
    io_.stop();
    if (ioThread_.joinable()) {
        ioThread_.join();
    }
}

void FileServer::DoAccept() {
    auto socket = std::make_shared<SslSocket>(io_, sslContext_);
    acceptor_.async_accept(socket->lowest_layer(),
        [this, socket](const asio::error_code& ec) {
            if (!ec) {
                socket->async_handshake(asio::ssl::stream_base::server,
                    [socket](const asio::error_code& handshakeEc) {
                        if (!handshakeEc) {
                            std::cout << "[FileServer] Port2 connection established" << std::endl;
                        }
                    });
            }
            DoAccept();
        });
}
