#include "FileDownloadSink.h"
#include <stdexcept>

namespace dialhome::files {
FileDownloadSink::FileDownloadSink(std::filesystem::path destination)
    : destination_(std::move(destination)),
      stream_(destination_, std::ios::binary),
      ctx_(ZSTD_createDCtx()) {
    if (!stream_) {
        throw std::runtime_error("Unable to open download file: " + destination_.string());
    }
}

FileDownloadSink::~FileDownloadSink() {
    Complete();
    if (ctx_) {
        ZSTD_freeDCtx(ctx_);
    }
}

void FileDownloadSink::AppendChunk(const std::vector<uint8_t>& chunk, size_t expectedSize) {
    if (!ctx_) return;
    std::vector<uint8_t> buffer(expectedSize);
    size_t decoded = ZSTD_decompressDCtx(ctx_, buffer.data(), buffer.size(), chunk.data(), chunk.size());
    if (ZSTD_isError(decoded)) {
        throw std::runtime_error(ZSTD_getErrorName(decoded));
    }
    stream_.write(reinterpret_cast<const char*>(buffer.data()), decoded);
}

void FileDownloadSink::Complete() {
    if (stream_.is_open()) {
        stream_.flush();
        stream_.close();
    }
}
}
