#include "FileTransferClient.h"

namespace dialhome::files {
FileTransferClient::FileTransferClient(asio::io_context& io,
                                       const std::filesystem::path& trustedCert)
    : sslContext_(asio::ssl::context::tls_client) {
    if (std::filesystem::exists(trustedCert)) {
        sslContext_.load_verify_file(trustedCert.string());
    } else {
        sslContext_.set_verify_mode(asio::ssl::verify_none);
    }
    stream_ = std::make_unique<asio::ssl::stream<asio::ip::tcp::socket>>(io, sslContext_);
}

void FileTransferClient::Start(const std::string& host, unsigned short port,
                               std::function<void(const asio::error_code&)> onConnected) {
    connectHandler_ = std::move(onConnected);
    asio::ip::tcp::resolver resolver(stream_->get_executor());
    auto results = resolver.resolve(host, std::to_string(port));
    asio::async_connect(stream_->lowest_layer(), results,
        [this](const asio::error_code& ec, const asio::ip::tcp::endpoint&) {
            if (!ec) {
                stream_->async_handshake(asio::ssl::stream_base::client,
                    [this](const asio::error_code& handshakeEc) {
                        if (connectHandler_) {
                            connectHandler_(handshakeEc);
                        }
                    });
            } else if (connectHandler_) {
                connectHandler_(ec);
            }
        });
}

void FileTransferClient::SendChunk(const std::vector<uint8_t>& data,
                                   std::function<void(const asio::error_code&)> onSent) {
    asio::async_write(*stream_, asio::buffer(data),
        [onSent](const asio::error_code& ec, std::size_t) {
            if (onSent) onSent(ec);
        });
}

void FileTransferClient::Close() {
    asio::error_code ec;
    stream_->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ec);
    stream_->lowest_layer().close(ec);
}
}
