void StreamingMetrics::RecordFrame(std::chrono::milliseconds latency) {
    frames_.fetch_add(1, std::memory_order_relaxed);
    latencySum_.fetch_add(latency.count(), std::memory_order_relaxed);
}

double StreamingMetrics::AverageLatency() const {
    int count = frames_.load(std::memory_order_relaxed);
    if (count == 0) return 0.0;
    return static_cast<double>(latencySum_.load(std::memory_order_relaxed)) / count;
}

