namespace dialhome::remote {
HeartbeatService::HeartbeatService(asio::io_context& io, std::chrono::seconds interval)
    : io_(io), interval_(interval) {}

void HeartbeatService::Start(std::function<void()> callback) {
    callback_ = std::move(callback);
    timer_ = std::make_unique<asio::steady_timer>(io_);
    running_ = true;
    Schedule();
}

void HeartbeatService::Stop() {
    running_ = false;
    if (timer_) {
        timer_->cancel();
    }
}

void HeartbeatService::Schedule() {
    if (!running_) return;
    timer_->expires_after(interval_);
    timer_->async_wait([this](const asio::error_code& ec) {
        if (!ec && callback_) {
            callback_();
        }
        Schedule();
    });
}
}

