#include "remote_host/net/DialHomeClient.h"

namespace dialhome::remote {
namespace {
struct LaunchOptions {
    std::string host = "control-laptop.local";
    unsigned short port = 5001;
    std::filesystem::path configPath = std::filesystem::path("configs") / "remote_host.toml";
    std::filesystem::path tlsCertPath = std::filesystem::path("configs") / "control_laptop.crt";
};

std::string Trim(std::string text) {
    auto notSpace = [](unsigned char ch) { return !std::isspace(ch); };
    text.erase(text.begin(), std::find_if(text.begin(), text.end(), notSpace));
    text.erase(std::find_if(text.rbegin(), text.rend(), notSpace).base(), text.end());
    return text;
}

std::string StripQuotes(const std::string& value) {
    if (value.size() >= 2 && ((value.front() == '"' && value.back() == '"') || (value.front() == '\'' && value.back() == '\''))) {
        return value.substr(1, value.size() - 2);
    }
    return value;
}

std::string ExpandEnvTokens(const std::string& value) {
    std::string result;
    for (size_t i = 0; i < value.size();) {
        if (value[i] == '%' && i + 1 < value.size()) {
            size_t end = value.find('%', i + 1);
            if (end != std::string::npos) {
                auto name = value.substr(i + 1, end - i - 1);
                if (!name.empty()) {
                    if (const char* env = std::getenv(name.c_str())) {
                        result += env;
                    }
                    i = end + 1;
                    continue;
                }
            }
        }
        result += value[i++];
    }
    return result;
}

std::optional<std::string> NextArgValue(int argc, char* argv[], int& index) {
    if (index + 1 >= argc) {
        return std::nullopt;
    }
    return std::string(argv[++index]);
}

unsigned short ParsePort(const std::string& text) {
    auto value = std::stoul(text);
    if (value > std::numeric_limits<unsigned short>::max()) {
        throw std::out_of_range("Port value out of range");
    }
    return static_cast<unsigned short>(value);
}

void ApplyConfigPair(const std::string& section, const std::string& key, const std::string& value, LaunchOptions& options) {
    if (section == "network") {
        if (key == "ddns_host") {
            options.host = value;
        } else if (key == "port1") {
            options.port = ParsePort(value);
        } else if (key == "control_cert_path") {
            options.tlsCertPath = value;
        }
    }
}

void LoadToml(const std::filesystem::path& path, LaunchOptions& options) {
    if (!std::filesystem::exists(path)) {
        return;
    }
    std::ifstream file(path);
    if (!file) {
        return;
    }
    std::string line;
    std::string section;
    while (std::getline(file, line)) {
        auto trimmed = Trim(line);
        if (trimmed.empty() || trimmed[0] == '#') {
            continue;
        }
        if (trimmed.front() == '[' && trimmed.back() == ']') {
            section = trimmed.substr(1, trimmed.size() - 2);
            continue;
        }
        auto eqPos = trimmed.find('=');
        if (eqPos == std::string::npos) {
            continue;
        }
        auto key = Trim(trimmed.substr(0, eqPos));
        auto value = Trim(trimmed.substr(eqPos + 1));
        auto commentPos = value.find('#');
        if (commentPos != std::string::npos) {
            value = value.substr(0, commentPos);
        }
        value = Trim(value);
        value = StripQuotes(value);
        value = ExpandEnvTokens(value);
        if (!value.empty()) {
            ApplyConfigPair(section, key, value, options);
        }
    }
}

void ApplyEnvOverrides(LaunchOptions& options) {
    if (const char* host = std::getenv("DIALHOME_HOST")) {
        options.host = host;
    }
    if (const char* port = std::getenv("DIALHOME_PORT")) {
        options.port = ParsePort(port);
    }
    if (const char* cert = std::getenv("DIALHOME_CONTROL_CERT")) {
        options.tlsCertPath = ExpandEnvTokens(cert);
    }
}

LaunchOptions ParseArguments(int argc, char* argv[]) {
    LaunchOptions options;
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "--config") {
            auto value = NextArgValue(argc, argv, i);
            if (!value) {
                throw std::invalid_argument("--config requires a path");
            }
            options.configPath = ExpandEnvTokens(*value);
        }
    }

    LoadToml(options.configPath, options);
    ApplyEnvOverrides(options);

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "--host") {
            auto value = NextArgValue(argc, argv, i);
            if (!value) {
                throw std::invalid_argument("--host requires a value");
            }
            options.host = *value;
        } else if (arg == "--port") {
            auto value = NextArgValue(argc, argv, i);
            if (!value) {
                throw std::invalid_argument("--port requires a value");
            }
            options.port = ParsePort(*value);
        } else if (arg == "--cert") {
            auto value = NextArgValue(argc, argv, i);
            if (!value) {
                throw std::invalid_argument("--cert requires a path");
            }
            options.tlsCertPath = ExpandEnvTokens(*value);
        }
    }

    return options;
}

class ShutdownLatch {
public:
    ShutdownLatch() {
        instance_ = this;
        SetConsoleCtrlHandler(&ShutdownLatch::HandleSignal, TRUE);
    }

    ~ShutdownLatch() {
        SetConsoleCtrlHandler(&ShutdownLatch::HandleSignal, FALSE);
        instance_ = nullptr;
    }

    void Wait() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return stopRequested_; });
    }

    void Signal() {
        std::lock_guard<std::mutex> lock(mutex_);
        stopRequested_ = true;
        cv_.notify_all();
    }

private:
    static BOOL WINAPI HandleSignal(DWORD type) {
        switch (type) {
            case CTRL_C_EVENT:
            case CTRL_BREAK_EVENT:
            case CTRL_CLOSE_EVENT:
            case CTRL_LOGOFF_EVENT:
            case CTRL_SHUTDOWN_EVENT:
                if (instance_) {
                    instance_->Signal();
                }
                return TRUE;
            default:
                return FALSE;
        }
    }

    static ShutdownLatch* instance_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stopRequested_ = false;
};

ShutdownLatch* ShutdownLatch::instance_ = nullptr;

}  // namespace

int main(int argc, char* argv[]) {
    try {
        auto options = ParseArguments(argc, argv);
        std::cout << "[RemoteHost] dialing " << options.host << ":" << options.port;
        if (!options.tlsCertPath.empty()) {
            std::cout << " using cert " << options.tlsCertPath.string();
        }
        std::cout << std::endl;

        DialHomeClient client(options.host, options.port, options.tlsCertPath);
        client.Start();

        std::cout << "[RemoteHost] Press Ctrl+C to disconnect" << std::endl;
        ShutdownLatch latch;
        latch.Wait();

        std::cout << "[RemoteHost] Shutdown requested" << std::endl;
        client.Stop();
        std::cout << "[RemoteHost] Disconnected" << std::endl;
    } catch (const std::exception& ex) {
        std::cerr << "[RemoteHost] fatal error: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

}  // namespace dialhome::remote
