    }
    return static_cast<unsigned short>(value);
}

void ApplyConfigPair(const std::string& section, const std::string& key, const std::string& value, AppOptions& options) {
    if (section == "network") {
        if (key == "port1") {
            options.port1 = ParsePort(value);
        } else if (key == "port2") {
            options.port2 = ParsePort(value);
        }
    } else if (section == "tls") {
        if (key == "cert_path") {
            options.certPath = value;
        } else if (key == "key_path") {
            options.keyPath = ExpandEnvTokens(value);
        }
    }
