class ShutdownLatch {
public:
    ShutdownLatch() {
        instance_ = this;
        SetConsoleCtrlHandler(&ShutdownLatch::HandleSignal, TRUE);
    }

    ~ShutdownLatch() {
        SetConsoleCtrlHandler(&ShutdownLatch::HandleSignal, FALSE);
        instance_ = nullptr;
    }

    void Wait() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return stopRequested_; });
    }

    void Signal() {
        std::lock_guard<std::mutex> lock(mutex_);
        stopRequested_ = true;
        cv_.notify_all();
    }

private:
    static BOOL WINAPI HandleSignal(DWORD type) {
        switch (type) {
            case CTRL_C_EVENT:
            case CTRL_BREAK_EVENT:
            case CTRL_CLOSE_EVENT:
            case CTRL_LOGOFF_EVENT:
            case CTRL_SHUTDOWN_EVENT:
                if (instance_) {
                    instance_->Signal();
                }
                return TRUE;
            default:
                return FALSE;
        }
    }

    static ShutdownLatch* instance_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stopRequested_ = false;
};

ShutdownLatch* ShutdownLatch::instance_ = nullptr;

