bool MainFrame::CreateMenus() {
    CMenu menuBar;
    if (!menuBar.CreateMenu()) {
        return false;
    }

    CMenu fileMenu;
    if (!fileMenu.CreatePopupMenu()) {
        return false;
    }
    if (!fileMenu.AppendMenu(MF_STRING, ID_APP_EXIT, _T("Exit"))) {
        return false;
    }

    CMenu viewMenu;
    if (!viewMenu.CreatePopupMenu()) {
        return false;
    }
    if (!viewMenu.AppendMenu(MF_STRING, ID_VIEW_FILE_MANAGER, _T("File Manager..."))) {
        return false;
    }

    if (!menuBar.AppendMenu(MF_POPUP | MF_STRING, reinterpret_cast<UINT_PTR>(fileMenu.Detach()), _T("File"))) {
        return false;
    }
    if (!menuBar.AppendMenu(MF_POPUP | MF_STRING, reinterpret_cast<UINT_PTR>(viewMenu.Detach()), _T("View"))) {
        return false;
    }

    menuHandle_ = menuBar.Detach();
    if (!menuHandle_) {
        return false;
    }
    if (!::SetMenu(GetSafeHwnd(), menuHandle_)) {
        ::DestroyMenu(menuHandle_);
        menuHandle_ = nullptr;
        return false;
    }
    DrawMenuBar();
    return true;
}

class ControlLaptopApp : public CWinApp {
public:
    BOOL InitInstance() override;
    int ExitInstance() override;

private:
    void StartServers(const AppOptions& options);

    AppOptions options_;
    std::unique_ptr<control::ControlServer> controlServer_;
    std::unique_ptr<control::FileServer> fileServer_;
};

BOOL ControlLaptopApp::InitInstance() {
    try {
        options_ = ParseArguments(__argc, __argv);
        StartServers(options_);
    } catch (const std::exception& ex) {
        MessageBoxA(nullptr, ex.what(), "ControlLaptop", MB_ICONERROR | MB_OK);
        return FALSE;
    }

    INITCOMMONCONTROLSEX controls{sizeof(INITCOMMONCONTROLSEX)};
    controls.dwICC = ICC_STANDARD_CLASSES | ICC_TREEVIEW_CLASSES | ICC_LISTVIEW_CLASSES;
    InitCommonControlsEx(&controls);

    auto frame = std::make_unique<MainFrame>();
    if (!frame->GetSafeHwnd()) {
        return FALSE;
    }
    m_pMainWnd = frame.get();
    frame->ShowWindow(SW_SHOW);
    frame->UpdateWindow();
    frame.release();
    return TRUE;
}

int ControlLaptopApp::ExitInstance() {
    if (fileServer_) {
        fileServer_->Stop();
        fileServer_.reset();
    }
    if (controlServer_) {
        controlServer_->Stop();
        controlServer_.reset();
    }
    return CWinApp::ExitInstance();
}

void ControlLaptopApp::StartServers(const AppOptions& options) {
    auth::PasscodeHasher hasher(options.passcodeSecretPath.string());
    auto passcode = hasher.Hash();
    controlServer_ = std::make_unique<control::ControlServer>(options.port1, options.certPath, options.keyPath, passcode);
    controlServer_->Start();
    fileServer_ = std::make_unique<control::FileServer>(options.port2, options.certPath, options.keyPath, passcode);
    fileServer_->Start();
}

