    asio::post(io_, [this]() {
        if (!stream_ || !authenticated_) {
            return;
        }
        auto buffer = std::make_shared<std::array<unsigned char, 1>>();
        (*buffer)[0] = 'H';
        asio::async_write(*stream_, asio::buffer(*buffer),
            [buffer](const asio::error_code& ec, std::size_t) {
                if (ec) {
                    std::cerr << "[DialHomeClient] Heartbeat send failed: " << ec.message() << std::endl;
                }
            });
    });
    return true;
}
