void ControlServer::VerifyPasscode(std::shared_ptr<SslSocket> socket) {
    auto buffer = std::make_shared<std::array<unsigned char, 32>>();
    asio::async_read(*socket, asio::buffer(*buffer),
        [this, socket, buffer](const asio::error_code& ec, std::size_t bytesTransferred) {
            if (!ec && bytesTransferred == buffer->size() && *buffer == expectedPasscode_) {
                BeginSession(socket);
            } else {
                std::cerr << "[ControlServer] Passcode verification failed" << std::endl;
                heartbeatEvents_.LogTlsFailure(ec ? ec.message() : std::string("bad_passcode"));
                asio::error_code ignored;
                socket->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ignored);
                socket->lowest_layer().close(ignored);
            }
        });
}
}

void ControlServer::BeginSession(std::shared_ptr<SslSocket> socket) {
    std::cout << "[ControlServer] Device authenticated" << std::endl;
    heartbeatEvents_.LogTlsSuccess();
    heartbeatMonitor_.RecordBeat();
    ReadHeartbeat(std::move(socket));
}

void ControlServer::ReadHeartbeat(std::shared_ptr<SslSocket> socket) {
    auto buffer = std::make_shared<std::array<unsigned char, 1>>();
    asio::async_read(*socket, asio::buffer(*buffer),
        [this, socket, buffer](const asio::error_code& ec, std::size_t bytesTransferred) {
            if (!ec && bytesTransferred == buffer->size()) {
                heartbeatMonitor_.RecordBeat();
                ReadHeartbeat(socket);
            } else if (ec != asio::error::operation_aborted) {
                HandleSessionError(ec, socket);
            }
        });
}

void ControlServer::HandleSessionError(const asio::error_code& ec, std::shared_ptr<SslSocket> socket) {
    if (ec) {
        std::cerr << "[ControlServer] Heartbeat stream closed: " << ec.message() << std::endl;
    }
    auto outage = heartbeatMonitor_.SecondsSinceLastBeat();
    if (outage) {
        heartbeatEvents_.LogHeartbeatOutage(static_cast<int>(outage->count()));
    }
    if (socket && socket->lowest_layer().is_open()) {
        asio::error_code ignored;
        socket->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ignored);
        socket->lowest_layer().close(ignored);
    }
}
