namespace dialhome::remote {
namespace {
constexpr auto kCaptureIdle = std::chrono::milliseconds(500);
constexpr auto kCaptureFrameDelay = std::chrono::milliseconds(16);

RECT ClampRect(const RECT& rect, LONG maxWidth, LONG maxHeight) {
    RECT result = rect;
    result.left = std::clamp(result.left, 0L, maxWidth);
    result.top = std::clamp(result.top, 0L, maxHeight);
    result.right = std::clamp(result.right, result.left, maxWidth);
    result.bottom = std::clamp(result.bottom, result.top, maxHeight);
    return result;
}
}  // namespace

RemoteAgent::RemoteAgent(LaunchOptions options)
    : options_(std::move(options)),
      passcodeHash_(auth::PasscodeHasher(options_.passcodeSecretPath.string()).Hash()),
      client_(options_.host, options_.port, options_.tlsCertPath, passcodeHash_),
      heartbeat_(heartbeatIo_, std::chrono::seconds(30)) {}

RemoteAgent::~RemoteAgent() {
    Stop();
}

bool RemoteAgent::Start() {
    if (running_.exchange(true)) {
        return true;
    }

    captureReady_ = capture_.Initialize();
    if (captureReady_) {
        std::cout << "[RemoteAgent] Screen capture initialized" << std::endl;
    } else {
        std::cout << "[RemoteAgent] Screen capture initialization failed" << std::endl;
    }

    client_.Start();

    heartbeat_.Start([this]() {
        if (!client_.SendHeartbeat()) {
            std::cout << "[RemoteAgent] Heartbeat waiting for authenticated session" << std::endl;
        }
    });

    heartbeatThread_ = std::thread([this] {
        try {
            heartbeatIo_.run();
        } catch (const std::exception& ex) {
            std::cerr << "[RemoteAgent] Heartbeat loop error: " << ex.what() << std::endl;
        }
    });

    captureThread_ = std::thread(&RemoteAgent::RunCaptureLoop, this);
    return true;
}

void RemoteAgent::Stop() {
    if (!running_.exchange(false)) {
        return;
    }

    heartbeat_.Stop();
    heartbeatIo_.stop();
    if (heartbeatThread_.joinable()) {
        heartbeatThread_.join();
    }
    heartbeatIo_.restart();

    if (captureThread_.joinable()) {
        captureThread_.join();
    }

    client_.Stop();
}

void RemoteAgent::RunCaptureLoop() {
    using Microsoft::WRL::ComPtr;

    capture::DirtyRectEncoder encoder;
    ComPtr<ID3D11Texture2D> stagingTexture;
    D3D11_TEXTURE2D_DESC stagingDesc{};

    while (running_) {
        if (!captureReady_) {
            std::this_thread::sleep_for(kCaptureIdle);
            continue;
    }

        DXGI_OUTDUPL_FRAME_INFO frameInfo{};
        ComPtr<ID3D11Texture2D> gpuTexture;
        if (!capture_.AcquireFrame(frameInfo, gpuTexture)) {
            std::this_thread::sleep_for(kCaptureFrameDelay);
            continue;
        }

        bool frameHeld = true;
        auto releaseFrame = [&]() {
            if (frameHeld) {
                capture_.ReleaseFrame();
                frameHeld = false;
            }
        };

        if (!gpuTexture) {
            releaseFrame();
            continue;
        }

        const auto width = static_cast<LONG>(capture_.GetDesc().ModeDesc.Width);
        const auto height = static_cast<LONG>(capture_.GetDesc().ModeDesc.Height);
        auto dirtyRects = capture_.GetDirtyRects();
        if (dirtyRects.empty()) {
            dirtyRects.push_back(RECT{0, 0, width, height});
        }

        if (!stagingTexture || stagingDesc.Width != static_cast<UINT>(width) ||
            stagingDesc.Height != static_cast<UINT>(height)) {
            D3D11_TEXTURE2D_DESC desc{};
            gpuTexture->GetDesc(&desc);
            desc.BindFlags = 0;
            desc.MiscFlags = 0;
            desc.Usage = D3D11_USAGE_STAGING;
            desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
            if (FAILED(capture_.GetDevice()->CreateTexture2D(&desc, nullptr, &stagingTexture))) {
                std::cerr << "[RemoteAgent] Failed to allocate staging texture" << std::endl;
                releaseFrame();
                std::this_thread::sleep_for(kCaptureFrameDelay);
                continue;
            }
            stagingDesc = desc;
        }

        capture_.GetContext()->CopyResource(stagingTexture.Get(), gpuTexture.Get());

        D3D11_MAPPED_SUBRESOURCE mapped{};
        if (FAILED(capture_.GetContext()->Map(stagingTexture.Get(), 0, D3D11_MAP_READ, 0, &mapped))) {
            std::cerr << "[RemoteAgent] Failed to map staging texture" << std::endl;
            releaseFrame();
            std::this_thread::sleep_for(kCaptureFrameDelay);
            continue;
        }

        protocol::ScreenFrame frame;
        const auto* base = static_cast<const uint8_t*>(mapped.pData);
        for (const auto& dirty : dirtyRects) {
            RECT rect = ClampRect(dirty, width, height);
            int rectWidth = rect.right - rect.left;
            int rectHeight = rect.bottom - rect.top;
            if (rectWidth <= 0 || rectHeight <= 0) {
                continue;
            }

            std::vector<uint8_t> raw(rectWidth * rectHeight * 4);
            for (int y = 0; y < rectHeight; ++y) {
                const auto* src = base + (rect.top + y) * mapped.RowPitch + rect.left * 4;
                std::memcpy(raw.data() + y * rectWidth * 4, src, rectWidth * 4);
            }

            protocol::RectPacket packet;
            packet.x = rect.left;
            packet.y = rect.top;
            packet.width = rectWidth;
            packet.height = rectHeight;
            packet.data = encoder.Compress(raw.data(), raw.size());
            frame.rects.push_back(std::move(packet));
        }

        capture_.GetContext()->Unmap(stagingTexture.Get(), 0);
        releaseFrame();

        if (!frame.rects.empty()) {
            client_.SendScreenFrame(frame);
        }
    }
}
}  // namespace dialhome::remote
