#include <iostream>\r\n#include <utility>\r\n#include <vector>

namespace dialhome::control {
namespace {
using SslSocket = ControlServer::SslSocket;
}

struct ControlServer::Session : std::enable_shared_from_this<ControlServer::Session> {
    Session(ControlServer& server, std::shared_ptr<SslSocket> socket)
        : server_(server), socket_(std::move(socket)) {}

    void Start() {
        server_.heartbeatEvents_.LogTlsSuccess();
        server_.heartbeatMonitor_.RecordBeat();
        ReadHeader();
    }

private:
    void ReadHeader() {
        if (!socket_) {
            return;
        }
        auto self = shared_from_this();
        asio::async_read(*socket_, asio::buffer(headerBuffer_),
            [self](const asio::error_code& ec, std::size_t bytesTransferred) {
                if (ec || bytesTransferred != self->headerBuffer_.size()) {
                    self->HandleError(ec);
                    return;
                }
                try {
                    self->currentHeader_ = protocol::DecodeHeader(self->headerBuffer_);
                } catch (const std::exception& ex) {
                    std::cerr << "[ControlServer] Failed to decode header: " << ex.what() << std::endl;
                    self->HandleError(asio::error::operation_aborted);
                    return;
                }
                if (self->currentHeader_.payloadSize == 0) {
                    self->payload_.clear();
                    self->HandleMessage();
                    self->ReadHeader();
                    return;
                }
                self->payload_.assign(self->currentHeader_.payloadSize, 0);
                self->ReadPayload();
            });
    }

    void ReadPayload() {
        auto self = shared_from_this();
        asio::async_read(*socket_, asio::buffer(payload_),
            [self](const asio::error_code& ec, std::size_t bytesTransferred) {
                if (ec || bytesTransferred != self->payload_.size()) {
                    self->HandleError(ec);
                    return;
                }
                self->HandleMessage();
                self->ReadHeader();
            });
    }

    void HandleMessage() {
        switch (currentHeader_.kind) {
            case protocol::MessageKind::Heartbeat:
                server_.heartbeatMonitor_.RecordBeat();
                break;
            case protocol::MessageKind::ScreenFrame: {
                if (!server_.frameCallback_) {
                    break;
                }
                try {
                    auto frame = protocol::DecodeScreenFrame(payload_);
                    server_.frameCallback_(frame);
                } catch (const std::exception& ex) {
                    std::cerr << "[ControlServer] Failed to decode ScreenFrame: " << ex.what() << std::endl;
                }
                break;
            }
            default:
                break;
        }
    }

    void HandleError(const asio::error_code& ec) {
        if (ec && ec != asio::error::operation_aborted) {
            std::cerr << "[ControlServer] Session error: " << ec.message() << std::endl;
        }
        if (auto outage = server_.heartbeatMonitor_.SecondsSinceLastBeat()) {
            server_.heartbeatEvents_.LogHeartbeatOutage(static_cast<int>(outage->count()));
        }
        if (socket_ && socket_->lowest_layer().is_open()) {
            asio::error_code ignored;
            socket_->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ignored);
            socket_->lowest_layer().close(ignored);
        }
        std::lock_guard lock(server_.sessionMutex_);
        if (server_.activeSession_.get() == this) {
            server_.activeSession_.reset();
        }
    }

    ControlServer& server_;
    std::shared_ptr<SslSocket> socket_;
    std::array<uint8_t, protocol::kMessageHeaderSize> headerBuffer_{};
    std::vector<uint8_t> payload_;
    protocol::MessageHeader currentHeader_{protocol::MessageKind::Heartbeat, 0};
};

ControlServer::ControlServer(unsigned short port,
                             const std::filesystem::path& certFile,
                             const std::filesystem::path& keyFile,
                             std::array<unsigned char, 32> expectedPasscode,
                             const std::filesystem::path& logDir,
                             std::function<void(const protocol::ScreenFrame&)> frameCallback)
    : sslContext_(asio::ssl::context::tls_server),
      acceptor_(io_, asio::ip::tcp::endpoint(asio::ip::tcp::v4(), port)),
      certFile_(certFile),
      keyFile_(keyFile),
      expectedPasscode_(expectedPasscode),
      telemetryLogger_(logDir),
      heartbeatEvents_(telemetryLogger_),
      frameCallback_(std::move(frameCallback)) {
    sslContext_.set_options(asio::ssl::context::default_workarounds |
                            asio::ssl::context::no_sslv2 |
                            asio::ssl::context::no_sslv3 |
                            asio::ssl::context::single_dh_use);
    if (std::filesystem::exists(certFile_)) {
        sslContext_.use_certificate_chain_file(certFile_.string());
    }
    if (std::filesystem::exists(keyFile_)) {
        sslContext_.use_private_key_file(keyFile_.string(), asio::ssl::context::pem);
    }
}

ControlServer::~ControlServer() { Stop(); }

void ControlServer::Start() {
    DoAccept();
    ioThread_ = std::thread([this] {
        try {
            io_.run();
        } catch (const std::exception& ex) {
            std::cerr << "ControlServer io_context error: " << ex.what() << std::endl;
        }
    });
}

void ControlServer::Stop() {
    io_.stop();
    if (ioThread_.joinable()) {
        ioThread_.join();
    }
    std::lock_guard lock(sessionMutex_);
    activeSession_.reset();
}

void ControlServer::DoAccept() {
    auto socket = std::make_shared<SslSocket>(io_, sslContext_);
    acceptor_.async_accept(socket->lowest_layer(),
        [this, socket](const asio::error_code& ec) {
            if (!ec) {
                socket->lowest_layer().set_option(asio::ip::tcp::no_delay(true));
                socket->async_handshake(asio::ssl::stream_base::server,
                    [this, socket](const asio::error_code& handshakeEc) {
                        if (!handshakeEc) {
                            VerifyPasscode(socket);
                        } else {
                            std::cerr << "[ControlServer] TLS handshake failed: " << handshakeEc.message() << std::endl;
                            heartbeatEvents_.LogTlsFailure(handshakeEc.message());
                        }
                    });
            }
            DoAccept();
        });
}

void ControlServer::VerifyPasscode(std::shared_ptr<SslSocket> socket) {
    auto buffer = std::make_shared<std::array<unsigned char, 32>>();
    asio::async_read(*socket, asio::buffer(*buffer),
        [this, socket, buffer](const asio::error_code& ec, std::size_t bytesTransferred) {
            if (!ec && bytesTransferred == buffer->size() && *buffer == expectedPasscode_) {
                StartSession(socket);
            } else {
                std::cerr << "[ControlServer] Passcode verification failed" << std::endl;
                heartbeatEvents_.LogTlsFailure(ec ? ec.message() : std::string("bad_passcode"));
                asio::error_code ignored;
                socket->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ignored);
                socket->lowest_layer().close(ignored);
            }
        });
}

void ControlServer::StartSession(std::shared_ptr<SslSocket> socket) {
    auto session = std::make_shared<Session>(*this, std::move(socket));
    {
        std::lock_guard lock(sessionMutex_);
        activeSession_ = session;
    }
    session->Start();
}
