namespace dialhome {
namespace {
constexpr UINT ID_VIEW_FILE_MANAGER = 0x2001;
constexpr UINT ID_VIEWPORT_CTRL = 0x3001;
constexpr UINT WM_REMOTE_FRAME = WM_APP + 1;

struct FrameMessagePayload {
    protocol::ScreenFrame frame;
};

struct AppOptions {
    unsigned short port1 = 5001;
    unsigned short port2 = 5002;
    std::filesystem::path configPath = std::filesystem::path("configs") / "control_laptop.toml";
    std::filesystem::path certPath = std::filesystem::path("configs") / "control_laptop.crt";
    std::filesystem::path keyPath = std::filesystem::path("configs") / "control_laptop.key";
    std::filesystem::path passcodeSecretPath = std::filesystem::path("configs") / "passcode.secret";
    std::filesystem::path logDir = std::filesystem::path("logs") / "control";
};

std::string Trim(std::string text) {
    auto notSpace = [](unsigned char ch) { return !std::isspace(ch); };
    text.erase(text.begin(), std::find_if(text.begin(), text.end(), notSpace));
    text.erase(std::find_if(text.rbegin(), text.rend(), notSpace).base(), text.end());
    return text;
}

std::string StripQuotes(const std::string& value) {
    if (value.size() >= 2 && ((value.front() == '"' && value.back() == '"') || (value.front() == '\'' && value.back() == '\''))) {
        return value.substr(1, value.size() - 2);
    }
    return value;
}

std::string ExpandEnvTokens(const std::string& value) {
    std::string result;
    for (size_t i = 0; i < value.size();) {
        if (value[i] == '%' && i + 1 < value.size()) {
            size_t end = value.find('%', i + 1);
            if (end != std::string::npos) {
                auto name = value.substr(i + 1, end - i - 1);
                if (!name.empty()) {
                    if (const char* env = std::getenv(name.c_str())) {
                        result += env;
                    }
                    i = end + 1;
                    continue;
                }
            }
        }
        result += value[i++];
    }
    return result;
}

std::optional<std::string> NextArgValue(int argc, char* argv[], int& index) {
    if (index + 1 >= argc) {
        return std::nullopt;
    }
    return std::string(argv[++index]);
}

unsigned short ParsePort(const std::string& text) {
    auto value = std::stoul(text);
    if (value > std::numeric_limits<unsigned short>::max()) {
        throw std::out_of_range("Port value out of range");
    }
    return static_cast<unsigned short>(value);
}

void ApplyConfigPair(const std::string& section, const std::string& key, const std::string& value, AppOptions& options) {
    if (section == "network") {
        if (key == "port1") {
            options.port1 = ParsePort(value);
        } else if (key == "port2") {
            options.port2 = ParsePort(value);
        }
    } else if (section == "tls") {
        if (key == "cert_path") {
            options.certPath = ExpandEnvTokens(value);
        } else if (key == "key_path") {
            options.keyPath = ExpandEnvTokens(value);
        }
    } else if (section == "auth") {
        if (key == "passcode_secret_path") {
            options.passcodeSecretPath = ExpandEnvTokens(value);
        }
    } else if (section == "logging") {
        if (key == "output_dir") {
            options.logDir = ExpandEnvTokens(value);
        }
    }
}

void LoadToml(const std::filesystem::path& path, AppOptions& options) {
    if (!std::filesystem::exists(path)) {
        return;
    }
    std::ifstream file(path);
    if (!file) {
        return;
    }
    std::string section;
    std::string line;
    while (std::getline(file, line)) {
        line = Trim(line);
        if (line.empty() || line[0] == '#' || line[0] == ';') {
            continue;
        }
        if (line.front() == '[' && line.back() == ']') {
            section = line.substr(1, line.size() - 2);
            section = Trim(section);
            std::transform(section.begin(), section.end(), section.begin(), [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
            continue;
        }
        auto equalPos = line.find('=');
        if (equalPos == std::string::npos) {
            continue;
        }
        auto key = Trim(line.substr(0, equalPos));
        auto value = Trim(line.substr(equalPos + 1));
        key = StripQuotes(key);
        value = StripQuotes(value);
        std::transform(key.begin(), key.end(), key.begin(), [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
        ApplyConfigPair(section, key, value, options);
    }
}

AppOptions ParseArguments(int argc, char* argv[]) {
    AppOptions options;
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if ((arg == "--config" || arg == "-c") && i + 1 < argc) {
            options.configPath = ExpandEnvTokens(argv[++i]);
        }
    }
    LoadToml(options.configPath, options);
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "--port1" && i + 1 < argc) {
            options.port1 = ParsePort(argv[++i]);
        } else if (arg == "--port2" && i + 1 < argc) {
            options.port2 = ParsePort(argv[++i]);
        } else if (arg == "--cert" && i + 1 < argc) {
            options.certPath = ExpandEnvTokens(argv[++i]);
        } else if (arg == "--key" && i + 1 < argc) {
            options.keyPath = ExpandEnvTokens(argv[++i]);
        } else if (arg == "--passcode" && i + 1 < argc) {
            options.passcodeSecretPath = ExpandEnvTokens(argv[++i]);
        } else if (arg == "--log-dir" && i + 1 < argc) {
            options.logDir = ExpandEnvTokens(argv[++i]);
        }
    }
    return options;
}
