class MainFrame : public CFrameWnd {
public:
    MainFrame();

    void PostScreenFrame(const protocol::ScreenFrame& frame);

protected:
    afx_msg int OnCreate(LPCREATESTRUCT createStruct);
    afx_msg void OnSize(UINT type, int cx, int cy);
    afx_msg void OnDestroy();
    afx_msg void OnFileExit();
    afx_msg void OnViewFileManager();
    afx_msg LRESULT OnRemoteFrame(WPARAM wParam, LPARAM lParam);

    DECLARE_MESSAGE_MAP()

private:
    bool CreateMenus();
    void LayoutViewport(int width, int height);

    ui::ViewportWnd viewport_;
    stream::FrameAssembler frameAssembler_;
    HMENU menuHandle_ = nullptr;
};

BEGIN_MESSAGE_MAP(MainFrame, CFrameWnd)
    ON_WM_CREATE()
    ON_WM_SIZE()
    ON_WM_DESTROY()
    ON_COMMAND(ID_APP_EXIT, &MainFrame::OnFileExit)
    ON_COMMAND(ID_VIEW_FILE_MANAGER, &MainFrame::OnViewFileManager)
    ON_MESSAGE(WM_REMOTE_FRAME, &MainFrame::OnRemoteFrame)
END_MESSAGE_MAP()

MainFrame::MainFrame() : frameAssembler_(viewport_) {
    CString title = _T("Dial-Home Control Laptop");
    Create(nullptr, title, WS_OVERLAPPEDWINDOW, CRect(100, 100, 1400, 900));
}

void MainFrame::PostScreenFrame(const protocol::ScreenFrame& frame) {
    auto payload = std::make_unique<FrameMessagePayload>();
    payload->frame = frame;
    PostMessage(WM_REMOTE_FRAME, reinterpret_cast<WPARAM>(payload.release()), 0);
}

int MainFrame::OnCreate(LPCREATESTRUCT createStruct) {
    if (CFrameWnd::OnCreate(createStruct) == -1) {
        return -1;
    }
    if (!CreateMenus()) {
        return -1;
    }
    CRect rect;
    GetClientRect(&rect);
    if (!viewport_.Create(_T(""), WS_CHILD | WS_VISIBLE | WS_BORDER, rect, this, ID_VIEWPORT_CTRL)) {
        return -1;
    }
    viewport_.UpdateFrame(std::max(1, rect.Width()), std::max(1, rect.Height()));
    return 0;
}

void MainFrame::OnSize(UINT type, int cx, int cy) {
    CFrameWnd::OnSize(type, cx, cy);
    LayoutViewport(cx, cy);
}

void MainFrame::LayoutViewport(int width, int height) {
    if (!::IsWindow(viewport_.GetSafeHwnd())) {
        return;
    }
    CRect rect(0, 0, width, height);
    viewport_.MoveWindow(rect);
}

void MainFrame::OnDestroy() {
    if (menuHandle_) {
        ::SetMenu(GetSafeHwnd(), nullptr);
        ::DestroyMenu(menuHandle_);
        menuHandle_ = nullptr;
    }
    CFrameWnd::OnDestroy();
}

void MainFrame::OnFileExit() {
    PostMessage(WM_CLOSE);
}

void MainFrame::OnViewFileManager() {
    ui::FileManagerDlg dlg;
    dlg.DoModal();
}

LRESULT MainFrame::OnRemoteFrame(WPARAM wParam, [[maybe_unused]] LPARAM lParam) {
    std::unique_ptr<FrameMessagePayload> payload(reinterpret_cast<FrameMessagePayload*>(wParam));
    if (payload) {
        frameAssembler_.ProcessFrame(payload->frame);
    }
    return 0;
}

bool MainFrame::CreateMenus() {
    CMenu menuBar;
    if (!menuBar.CreateMenu()) {
        return false;
    }

    CMenu fileMenu;
    if (!fileMenu.CreatePopupMenu()) {
        return false;
    }
    if (!fileMenu.AppendMenu(MF_STRING, ID_APP_EXIT, _T("Exit"))) {
        return false;
    }

    CMenu viewMenu;
    if (!viewMenu.CreatePopupMenu()) {
        return false;
    }
    if (!viewMenu.AppendMenu(MF_STRING, ID_VIEW_FILE_MANAGER, _T("File Manager..."))) {
        return false;
    }

    if (!menuBar.AppendMenu(MF_POPUP | MF_STRING, reinterpret_cast<UINT_PTR>(fileMenu.Detach()), _T("File"))) {
        return false;
    }
    if (!menuBar.AppendMenu(MF_POPUP | MF_STRING, reinterpret_cast<UINT_PTR>(viewMenu.Detach()), _T("View"))) {
        return false;
    }

    menuHandle_ = menuBar.Detach();
    if (!menuHandle_) {
        return false;
    }
    if (!::SetMenu(GetSafeHwnd(), menuHandle_)) {
        ::DestroyMenu(menuHandle_);
        menuHandle_ = nullptr;
        return false;
    }
    DrawMenuBar();
    return true;
}

class ControlLaptopApp : public CWinApp {
public:
    BOOL InitInstance() override;
    int ExitInstance() override;

private:
    void StartServers(const AppOptions& options, std::function<void(const protocol::ScreenFrame&)> frameCallback);

    AppOptions options_;
    std::unique_ptr<control::ControlServer> controlServer_;
    std::unique_ptr<control::FileServer> fileServer_;
};

BOOL ControlLaptopApp::InitInstance() {
    try {
        options_ = ParseArguments(__argc, __argv);
    } catch (const std::exception& ex) {
        MessageBoxA(nullptr, ex.what(), "ControlLaptop", MB_ICONERROR | MB_OK);
        return FALSE;
    }

    INITCOMMONCONTROLSEX controls{sizeof(INITCOMMONCONTROLSEX)};
    controls.dwICC = ICC_STANDARD_CLASSES | ICC_TREEVIEW_CLASSES | ICC_LISTVIEW_CLASSES;
    InitCommonControlsEx(&controls);

    if (!std::filesystem::exists(options_.logDir)) {
        std::filesystem::create_directories(options_.logDir);
    }

    auto frame = std::make_unique<MainFrame>();
    if (!frame->GetSafeHwnd()) {
        return FALSE;
    }

    auto framePtr = frame.get();
    StartServers(options_, [framePtr](const protocol::ScreenFrame& remoteFrame) {
        if (framePtr) {
            framePtr->PostScreenFrame(remoteFrame);
        }
    });

    m_pMainWnd = framePtr;
    frame->ShowWindow(SW_SHOW);
    frame->UpdateWindow();
    frame.release();
    return TRUE;
}

int ControlLaptopApp::ExitInstance() {
    if (fileServer_) {
        fileServer_->Stop();
        fileServer_.reset();
    }
    if (controlServer_) {
        controlServer_->Stop();
        controlServer_.reset();
    }
    return CWinApp::ExitInstance();
}

void ControlLaptopApp::StartServers(const AppOptions& options,
                                   std::function<void(const protocol::ScreenFrame&)> frameCallback) {
    auth::PasscodeHasher hasher(options.passcodeSecretPath.string());
    auto passcode = hasher.Hash();
    controlServer_ = std::make_unique<control::ControlServer>(options.port1,
                                                             options.certPath,
                                                             options.keyPath,
                                                             passcode,
                                                             options.logDir,
                                                             std::move(frameCallback));
    controlServer_->Start();
    fileServer_ = std::make_unique<control::FileServer>(options.port2, options.certPath, options.keyPath, passcode);
    fileServer_->Start();
}

}  // namespace dialhome

