std::vector<unsigned char> LoadSecret(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        throw std::runtime_error("Failed to open passcode secret: " + path);
    }
    return std::vector<unsigned char>((std::istreambuf_iterator<char>(file)),
                                      std::istreambuf_iterator<char>());
}
}

PasscodeHasher::PasscodeHasher(std::string secretPath)
    : secretPath_(std::move(secretPath)) {}

std::array<unsigned char, 32> PasscodeHasher::Hash() const {
    auto secret = LoadSecret(secretPath_);
    std::array<unsigned char, 32> digest{};
    SHA256(secret.data(), secret.size(), digest.data());
    return digest;
}
