    } else {
        sslContext_.set_verify_mode(asio::ssl::verify_none);
    }
}

DialHomeClient::~DialHomeClient() { Stop(); }

void DialHomeClient::Start() {
    ResolveAndConnect();
    ioThread_ = std::thread([this] {
        try {
            io_.run();
        } catch (const std::exception& ex) {
            std::cerr << "DialHomeClient io_context error: " << ex.what() << std::endl;
        }
    });
}

void DialHomeClient::Stop() {
    authenticated_ = false;
    io_.stop();
    if (ioThread_.joinable()) {
        ioThread_.join();
    }
    io_.restart();
}

bool DialHomeClient::SendHeartbeat() {
    if (!stream_ || !authenticated_) {
        return false;
    }
    SendMessage(protocol::MessageKind::Heartbeat, {});
    return true;
}

void DialHomeClient::SendScreenFrame(const protocol::ScreenFrame& frame) {
    if (!stream_ || !authenticated_) {
        return;
    }
    SendMessage(protocol::MessageKind::ScreenFrame, protocol::EncodeScreenFrame(frame));
}

void DialHomeClient::ResolveAndConnect() {
    auto results = resolver_.resolve(host_, std::to_string(port_));
    stream_ = std::make_unique<asio::ssl::stream<asio::ip::tcp::socket>>(io_, sslContext_);
    asio::async_connect(stream_->lowest_layer(), results,
        [this](const asio::error_code& ec, const asio::ip::tcp::endpoint&) {
            if (!ec) {
                stream_->async_handshake(asio::ssl::stream_base::client,
                    [this](const asio::error_code& handshakeEc) {
                        if (!handshakeEc) {
                            SendPasscode();
                            BeginRead();
                            std::cout << "[DialHomeClient] Connected to ControlLaptop" << std::endl;
                        } else {
                            authenticated_ = false;
                            std::cerr << "[DialHomeClient] Handshake failed: " << handshakeEc.message() << std::endl;
                        }
                    });
            } else {
                authenticated_ = false;
                std::cerr << "[DialHomeClient] Connect failed: " << ec.message() << std::endl;
            }
        });
}

void DialHomeClient::SendPasscode() {
    auto buffer = std::make_shared<std::array<unsigned char, 32>>(passcode_);
    asio::async_write(*stream_, asio::buffer(*buffer),
        [this, buffer](const asio::error_code& ec, std::size_t) {
            if (ec) {
                authenticated_ = false;
                std::cerr << "[DialHomeClient] Failed to send passcode: " << ec.message() << std::endl;
            } else {
                authenticated_ = true;
                std::cout << "[DialHomeClient] Passcode sent" << std::endl;
            }
        });
}

void DialHomeClient::BeginRead() {
    if (!stream_) {
        return;
    }
    asio::async_read(*stream_, asio::buffer(headerBuffer_),
        [this](const asio::error_code& ec, std::size_t bytesTransferred) {
            if (ec || bytesTransferred != headerBuffer_.size()) {
                std::cerr << "[DialHomeClient] Read header failed: " << ec.message() << std::endl;
                return;
            }
            try {
                currentHeader_ = protocol::DecodeHeader(headerBuffer_);
            } catch (const std::exception& ex) {
                std::cerr << "[DialHomeClient] Invalid header: " << ex.what() << std::endl;
                return;
            }
            if (currentHeader_.payloadSize == 0) {
                payloadBuffer_.clear();
                HandleIncomingMessage();
                BeginRead();
                return;
            }
            payloadBuffer_.assign(currentHeader_.payloadSize, 0);
            ReadPayload();
        });
}

void DialHomeClient::ReadPayload() {
    if (!stream_ || payloadBuffer_.empty()) {
        BeginRead();
        return;
    }
    asio::async_read(*stream_, asio::buffer(payloadBuffer_),
