}

void DialHomeClient::SendMessage(protocol::MessageKind kind, std::vector<uint8_t> payload) {
    auto headerBytes = protocol::EncodeHeader({kind, static_cast<uint32_t>(payload.size())});
    auto buffer = std::make_shared<std::vector<uint8_t>>();
    buffer->reserve(headerBytes.size() + payload.size());
    buffer->insert(buffer->end(), headerBytes.begin(), headerBytes.end());
    buffer->insert(buffer->end(), payload.begin(), payload.end());
    asio::post(writeStrand_, [this, buffer]() {
