MessageHeader DecodeHeaderInternal(const uint8_t* data, size_t length) {
    if (length != kMessageHeaderSize) {
        throw std::runtime_error("Invalid header length");
    }
    uint32_t type = 0;
    uint32_t size = 0;
    for (int i = 0; i < 4; ++i) {
        type |= static_cast<uint32_t>(data[i]) << (i * 8);
        size |= static_cast<uint32_t>(data[i + 4]) << (i * 8);
    }
    return MessageHeader{static_cast<MessageKind>(type), size};
}
}

std::array<uint8_t, kMessageHeaderSize> EncodeHeader(const MessageHeader& header) {
    std::array<uint8_t, kMessageHeaderSize> bytes{};
    uint32_t type = static_cast<uint32_t>(header.kind);
    for (int i = 0; i < 4; ++i) {
        bytes[i] = static_cast<uint8_t>((type >> (i * 8)) & 0xFF);
        bytes[i + 4] = static_cast<uint8_t>((header.payloadSize >> (i * 8)) & 0xFF);
    }
    return bytes;
}

MessageHeader DecodeHeader(const std::array<uint8_t, kMessageHeaderSize>& bytes) {
    return DecodeHeaderInternal(bytes.data(), bytes.size());
}

std::vector<uint8_t> EncodeScreenFrame(const ScreenFrame& frame) {
    std::vector<uint8_t> buffer;
    AppendUint32(buffer, static_cast<uint32_t>(frame.rects.size()));
    for (const auto& rect : frame.rects) {
        AppendInt32(buffer, rect.x);
        AppendInt32(buffer, rect.y);
        AppendInt32(buffer, rect.width);
        AppendInt32(buffer, rect.height);
        AppendUint32(buffer, static_cast<uint32_t>(rect.data.size()));
        buffer.insert(buffer.end(), rect.data.begin(), rect.data.end());
    }
    return buffer;
}

ScreenFrame DecodeScreenFrame(const std::vector<uint8_t>& buffer) {
    size_t offset = 0;
    ScreenFrame frame;
    uint32_t rectCount = ReadUint32(buffer, offset);
    frame.rects.reserve(rectCount);
    for (uint32_t i = 0; i < rectCount; ++i) {
        RectPacket packet;
        packet.x = ReadInt32(buffer, offset);
        packet.y = ReadInt32(buffer, offset);
        packet.width = ReadInt32(buffer, offset);
        packet.height = ReadInt32(buffer, offset);
        uint32_t dataSize = ReadUint32(buffer, offset);
        if (offset + dataSize > buffer.size()) {
            throw std::runtime_error("Buffer underrun while decoding rect data");
        }
        packet.data.assign(buffer.begin() + offset, buffer.begin() + offset + dataSize);
        offset += dataSize;
        frame.rects.push_back(std::move(packet));
    }
    return frame;
}

