#include "FileOpsClient.h"

namespace dialhome::files {
FileOpsClient::FileOpsClient(control::ControlServer& server)
    : server_(server) {
    server_.SetDirectoryResponseCallback(
        [this](const dialhome::protocol::DirectoryListResponse& response) { HandleResponse(response); });
}

void FileOpsClient::RequestList(const std::string& path, ResponseHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pending_[requestId] = std::move(handler);
    }

    if (!server_.RequestDirectoryList(requestId, path)) {
        DirectoryResult result;
        result.success = false;
        result.path = path;
        result.error = "Remote host not connected";
        ResponseHandler cb;
        {
            std::lock_guard lock(mutex_);
            auto it = pending_.find(requestId);
            if (it != pending_.end()) {
                cb = std::move(it->second);
                pending_.erase(it);
            }
        }
        if (cb) {
            cb(std::move(result));
        }
    }
}

void FileOpsClient::HandleResponse(const dialhome::protocol::DirectoryListResponse& response) {
    ResponseHandler handler;
    {
        std::lock_guard lock(mutex_);
        auto it = pending_.find(response.requestId);
        if (it != pending_.end()) {
            handler = std::move(it->second);
            pending_.erase(it);
        }
    }
    if (!handler) {
        return;
    }

    DirectoryResult result;
    result.success = response.success;
    result.path = response.path;
    result.entries = response.entries;
    result.error = response.error;
    handler(std::move(result));
}
}
