END_MESSAGE_MAP()

FileManagerDlg::FileManagerDlg(files::FileOpsClient* client)
    : CDialog(IDD, nullptr), fileOpsClient_(client) {}

BOOL FileManagerDlg::OnInitDialog() {
    CDialog::OnInitDialog();
    CRect rect;
    GetClientRect(&rect);
    tree_.Create(WS_VISIBLE | WS_CHILD | WS_BORDER | TVS_HASLINES | TVS_SHOWSELALWAYS,
                 CRect(10, 10, rect.Width() / 3, rect.Height() - 20), this, 1001);
    list_.Create(WS_VISIBLE | WS_CHILD | WS_BORDER | LVS_REPORT | LVS_SINGLESEL,
                 CRect(rect.Width() / 3 + 20, 10, rect.Width() - 10, rect.Height() - 20), this, 1002);
    list_.InsertColumn(0, _T("Name"), LVCFMT_LEFT, 240);
    list_.InsertColumn(1, _T("Size"), LVCFMT_RIGHT, 120);
    list_.InsertColumn(2, _T("Modified"), LVCFMT_LEFT, 200);
    RequestDirectory(std::string{});
    return TRUE;
}

void FileManagerDlg::RequestDirectory(const std::string& path) {
    if (!fileOpsClient_) {
        return;
    }
    fileOpsClient_->RequestList(path, [this](files::FileOpsClient::DirectoryResult result) {
        auto payload = new files::FileOpsClient::DirectoryResult(std::move(result));
        PostMessage(WM_FILEOPS_RESULT, reinterpret_cast<WPARAM>(payload), 0);
    });
}

void FileManagerDlg::UpdateList(const files::FileOpsClient::DirectoryResult& result) {
    currentPath_ = result.path;
    currentEntries_ = result.entries;
    list_.DeleteAllItems();

    int rowIndex = 0;
    for (size_t i = 0; i < currentEntries_.size(); ++i) {
        const auto& entry = currentEntries_[i];
        CString name(entry.name.c_str());
        int item = list_.InsertItem(rowIndex++, name);
        CString sizeText;
        if (entry.isDirectory) {
            sizeText = _T("<DIR>");
        } else {
            sizeText = FormatFileSize(entry.size);
        }
        list_.SetItemText(item, 1, sizeText);
        CString modified(entry.modified.c_str());
        list_.SetItemText(item, 2, modified);
        list_.SetItemData(item, static_cast<DWORD_PTR>(i));
    }

    PopulateTree(result);

    CString title;
    CString pathText(currentPath_.empty() ? _T("Remote") : currentPath_.c_str());
    title.Format(_T("Remote Files - %s"), pathText.GetString());
    SetWindowText(title);
}

void FileManagerDlg::PopulateTree(const files::FileOpsClient::DirectoryResult& result) {
    treeSelectionInternal_ = true;
    tree_.DeleteAllItems();
    treePaths_.clear();

    CString rootText(result.path.empty() ? _T("Remote") : result.path.c_str());
    HTREEITEM root = tree_.InsertItem(rootText);
    treePaths_[root] = result.path;

    if (!result.path.empty()) {
        HTREEITEM parentNode = tree_.InsertItem(_T(".."), root);
        treePaths_[parentNode] = ParentRemotePath(result.path);
    }

    for (const auto& entry : result.entries) {
        if (!entry.isDirectory) {
            continue;
        }
        CString name(entry.name.c_str());
        HTREEITEM child = tree_.InsertItem(name, root);
        treePaths_[child] = NormalizeChildPath(result.path, entry.name);
    }

    tree_.Expand(root, TVE_EXPAND);
    tree_.SelectItem(root);
    treeSelectionInternal_ = false;
}

LRESULT FileManagerDlg::OnDirectoryResult(WPARAM wParam, LPARAM) {
    std::unique_ptr<files::FileOpsClient::DirectoryResult> payload(
        reinterpret_cast<files::FileOpsClient::DirectoryResult*>(wParam));
    if (!payload) {
        return 0;
    }
    if (!payload->success) {
        CString message(payload->error.c_str());
        if (message.IsEmpty()) {
            message = _T("Unable to retrieve directory listing");
        }
        AfxMessageBox(message, MB_ICONERROR | MB_OK);
        return 0;
    }
    UpdateList(*payload);
    return 0;
}

void FileManagerDlg::OnTreeSelChanged(NMHDR* nmhdr, LRESULT* result) {
    if (result) {
        *result = 0;
    }
    if (treeSelectionInternal_ || !nmhdr) {
        return;
    }
    auto* info = reinterpret_cast<NM_TREEVIEW*>(nmhdr);
    HTREEITEM item = info->itemNew.hItem;
    if (!item) {
        return;
    }
    auto it = treePaths_.find(item);
    if (it == treePaths_.end()) {
        return;
    }
    if (it->second == currentPath_) {
        return;
    }
    RequestDirectory(it->second);
}

void FileManagerDlg::OnListDblClick(NMHDR*, LRESULT* result) {
    if (result) {
        *result = 0;
    }
    int item = list_.GetNextItem(-1, LVNI_SELECTED);
    if (item == -1) {
        return;
    }
    auto data = static_cast<int>(list_.GetItemData(item));
    if (data < 0 || static_cast<size_t>(data) >= currentEntries_.size()) {
        return;
    }
    const auto& entry = currentEntries_[static_cast<size_t>(data)];
    if (!entry.isDirectory) {
        return;
    }
    RequestDirectory(NormalizeChildPath(currentPath_, entry.name));
}
