void AppendUint32(std::vector<uint8_t>& buffer, uint32_t value) {
    for (int i = 0; i < 4; ++i) {
        buffer.push_back(static_cast<uint8_t>((value >> (i * 8)) & 0xFF));
    }
}

void AppendInt32(std::vector<uint8_t>& buffer, int32_t value) {
    AppendUint32(buffer, static_cast<uint32_t>(value));
}

uint32_t ReadUint32(const std::vector<uint8_t>& buffer, size_t& offset) {
    if (offset + 4 > buffer.size()) {
        throw std::runtime_error("Buffer underrun while decoding uint32");
    }
    uint32_t value = 0;
    for (int i = 0; i < 4; ++i) {
        value |= static_cast<uint32_t>(buffer[offset + i]) << (i * 8);
    }
    offset += 4;
    return value;
}

int32_t ReadInt32(const std::vector<uint8_t>& buffer, size_t& offset) {
    return static_cast<int32_t>(ReadUint32(buffer, offset));
}

void AppendUint64(std::vector<uint8_t>& buffer, uint64_t value) {
    for (int i = 0; i < 8; ++i) {
        buffer.push_back(static_cast<uint8_t>((value >> (i * 8)) & 0xFF));
    }
}

uint64_t ReadUint64(const std::vector<uint8_t>& buffer, size_t& offset) {
    if (offset + 8 > buffer.size()) {
        throw std::runtime_error("Buffer underrun while decoding uint64");
    }
    uint64_t value = 0;
    for (int i = 0; i < 8; ++i) {
        value |= static_cast<uint64_t>(buffer[offset + i]) << (i * 8);
    }
    offset += 8;
    return value;
}

void AppendString(std::vector<uint8_t>& buffer, const std::string& value) {
    AppendUint32(buffer, static_cast<uint32_t>(value.size()));
    buffer.insert(buffer.end(), value.begin(), value.end());
