std::string ReadString(const std::vector<uint8_t>& buffer, size_t& offset) {
    auto length = ReadUint32(buffer, offset);
    if (offset + length > buffer.size()) {
        throw std::runtime_error("Buffer underrun while decoding string");
    }
    std::string value(buffer.begin() + offset, buffer.begin() + offset + length);
    offset += length;
    return value;
