        offset += dataSize;
        frame.rects.push_back(std::move(packet));
    }
    return frame;
}

std::vector<uint8_t> EncodeInputEvent(const InputEvent& event) {
    std::vector<uint8_t> buffer;
    AppendUint32(buffer, static_cast<uint32_t>(event.type));
    AppendInt32(buffer, event.x);
    AppendInt32(buffer, event.y);
    AppendUint32(buffer, static_cast<uint32_t>(event.button));
    AppendUint32(buffer, event.pressed ? 1u : 0u);
    AppendUint32(buffer, event.keyCode);
    AppendUint32(buffer, event.modifiers);
    return buffer;
