}

std::vector<uint8_t> EncodeDirectoryListResponse(const DirectoryListResponse& response) {
    std::vector<uint8_t> buffer;
    AppendUint32(buffer, response.requestId);
    AppendUint32(buffer, response.success ? 1u : 0u);
    AppendString(buffer, response.path);
    if (response.success) {
        std::vector<uint8_t> entriesData;
        AppendUint32(entriesData, static_cast<uint32_t>(response.entries.size()));
