    }
    return buffer;
}

DirectoryListResponse DecodeDirectoryListResponse(const std::vector<uint8_t>& buffer) {
    size_t offset = 0;
    DirectoryListResponse response;
    response.requestId = ReadUint32(buffer, offset);
    response.success = ReadUint32(buffer, offset) != 0u;
    response.path = ReadString(buffer, offset);
