        auto count = ReadUint32(decompressed, entriesOffset);
        response.entries.reserve(count);
        for (uint32_t i = 0; i < count; ++i) {
            DirectoryEntry entry;
            entry.name = ReadString(decompressed, entriesOffset);
            entry.isDirectory = ReadUint32(decompressed, entriesOffset) != 0u;
            entry.size = ReadUint64(decompressed, entriesOffset);
            entry.modified = ReadString(decompressed, entriesOffset);
            response.entries.push_back(std::move(entry));
        }
    } else {
        response.error = ReadString(buffer, offset);
    }
    return response;
}
