CString FormatFileSize(uintmax_t size) {
    static LPCTSTR kUnits[] = {_T("B"), _T("KB"), _T("MB"), _T("GB"), _T("TB")};
    double value = static_cast<double>(size);
    constexpr size_t kUnitCount = sizeof(kUnits) / sizeof(kUnits[0]);
    size_t index = 0;
    while (value >= 1024.0 && index + 1 < kUnitCount) {
        value /= 1024.0;
        ++index;
    }
    CString formatted;
    if (index == 0) {
        formatted.Format(_T("%llu %s"), static_cast<unsigned long long>(size), kUnits[index]);
    } else {
        formatted.Format(_T("%.2f %s"), value, kUnits[index]);
    }
    return formatted;
}
