void FileDownloadSink::AppendChunk(const std::vector<uint8_t>& chunk, size_t expectedSize) {
    if (!ctx_) return;
    std::vector<uint8_t> buffer(expectedSize);
    size_t decoded = ZSTD_decompressDCtx(ctx_, buffer.data(), buffer.size(), chunk.data(), chunk.size());
    if (ZSTD_isError(decoded)) {
        throw std::runtime_error(ZSTD_getErrorName(decoded));
    }
    stream_.write(reinterpret_cast<const char*>(buffer.data()), decoded);
}

