        std::filesystem::path requested = request.path.empty() ? std::filesystem::current_path() : std::filesystem::path(request.path);
        std::filesystem::path normalized = std::filesystem::weakly_canonical(requested);
        response.path = normalized.string();
        response.entries = directoryService_.List(normalized);
        response.success = true;
    } catch (const std::exception& ex) {
        response.success = false;
        response.path = request.path;
        response.error = ex.what();
    }
    SendMessage(protocol::MessageKind::DirectoryListResponse, protocol::EncodeDirectoryListResponse(response));
}

void DialHomeClient::HandleFileTransferRequest(const protocol::FileTransferRequest& request) {
    protocol::FileTransferResponse response;
    response.requestId = request.requestId;
    try {
        std::filesystem::path path = request.path;
        if (!std::filesystem::exists(path)) {
            throw std::runtime_error("File not found");
        }
        std::ifstream file(path, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file");
        }
        response.data.assign(std::istreambuf_iterator<char>(file), std::istreambuf_iterator<char>());
        response.success = true;
    } catch (const std::exception& ex) {
        response.success = false;
        response.error = ex.what();
        response.data.clear();
    }
    SendFileTransferResponse(response);
}

void DialHomeClient::HandleFileUploadRequest(const protocol::FileUploadRequest& request) {
    protocol::FileUploadResult result;
    result.requestId = request.requestId;
    try {
        std::filesystem::path path = request.destinationPath;
        auto parent = path.parent_path();
        if (!parent.empty()) {
            std::filesystem::create_directories(parent);
        }
        std::ofstream file(path, std::ios::binary | std::ios::trunc);
        if (!file) {
            throw std::runtime_error("Failed to open destination file");
        }
        file.write(reinterpret_cast<const char*>(request.data.data()), static_cast<std::streamsize>(request.data.size()));
        if (!file) {
            throw std::runtime_error("Failed to write file contents");
        }
        result.success = true;
    } catch (const std::exception& ex) {
        result.success = false;
        result.error = ex.what();
    }
    SendFileUploadResult(result);
}

void DialHomeClient::SendFileTransferResponse(const protocol::FileTransferResponse& response) {
    SendMessage(protocol::MessageKind::FileTransferResponse, protocol::EncodeFileTransferResponse(response));
}

void DialHomeClient::SendFileUploadResult(const protocol::FileUploadResult& result) {
    SendMessage(protocol::MessageKind::FileUploadResult, protocol::EncodeFileUploadResult(result));
}



void DialHomeClient::ScheduleReconnect() {
    if (stopping_) {
        return;
    }
    reconnectTimer_.expires_after(std::chrono::seconds(2));
    reconnectTimer_.async_wait([this](const asio::error_code& ec) {
        if (!ec && !stopping_) {
            ResolveAndConnect();
        }
    });
}

void DialHomeClient::CloseStream() {
    if (!stream_) {
        return;
    }
    asio::error_code ignored;
    stream_->lowest_layer().shutdown(asio::ip::tcp::socket::shutdown_both, ignored);
    stream_->lowest_layer().close(ignored);
    stream_.reset();
}

void DialHomeClient::SendMessage(protocol::MessageKind kind, std::vector<uint8_t> payload) {
    auto headerBytes = protocol::EncodeHeader({kind, static_cast<uint32_t>(payload.size())});
    auto buffer = std::make_shared<std::vector<uint8_t>>();
    buffer->reserve(headerBytes.size() + payload.size());
    buffer->insert(buffer->end(), headerBytes.begin(), headerBytes.end());
    buffer->insert(buffer->end(), payload.begin(), payload.end());
    asio::post(writeStrand_, [this, buffer]() {
        if (!stream_) {
            return;
        }
        asio::async_write(*stream_, asio::buffer(*buffer),
            [buffer](const asio::error_code& ec, std::size_t) {
                if (ec) {
                    std::cerr << "[DialHomeClient] Send message failed: " << ec.message() << std::endl;
                }
            });
    });
}
