void FileTransferClient::Start(const std::string& host, unsigned short port,
                               std::function<void(const asio::error_code&)> onConnected) {
    connectHandler_ = std::move(onConnected);
    asio::ip::tcp::resolver resolver(stream_->get_executor());
    auto results = resolver.resolve(host, std::to_string(port));
    asio::async_connect(stream_->lowest_layer(), results,
        [this](const asio::error_code& ec, const asio::ip::tcp::endpoint&) {
