void MainFrame::PostScreenFrame(const protocol::ScreenFrame& frame) {
    auto payload = std::make_unique<FrameMessagePayload>();
    payload->frame = frame;
    PostMessage(WM_REMOTE_FRAME, reinterpret_cast<WPARAM>(payload.release()), 0);
}

void MainFrame::SetFileOpsClient(files::FileOpsClient* client) {
