#include "FileOpsClient.h"

namespace dialhome::files {
FileOpsClient::FileOpsClient(control::ControlServer& server)
    : server_(server) {
    server_.SetDirectoryResponseCallback(
        [this](const dialhome::protocol::DirectoryListResponse& response) { HandleResponse(response); });
    server_.SetFileTransferResponseCallback(
        [this](const dialhome::protocol::FileTransferResponse& response) { HandleFileTransferResponse(response); });
    server_.SetFileUploadResultCallback(
        [this](const dialhome::protocol::FileUploadResult& result) { HandleFileUploadResult(result); });
}

void FileOpsClient::RequestList(const std::string& path, ResponseHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pending_[requestId] = std::move(handler);
    }

    if (!server_.RequestDirectoryList(requestId, path)) {
        DirectoryResult result;
        result.success = false;
        result.path = path;
        result.error = "Remote host not connected";
        ResponseHandler cb;
        {
            std::lock_guard lock(mutex_);
            auto it = pending_.find(requestId);
            if (it != pending_.end()) {
                cb = std::move(it->second);
                pending_.erase(it);
            }
        }
        if (cb) {
            cb(std::move(result));
        }
    }
}

void FileOpsClient::RequestFile(const std::string& path,
                                protocol::FileTransferType type,
                                FileHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pendingFileTransfers_[requestId] = std::make_pair(path, std::move(handler));
    }
    if (!server_.RequestFileTransfer(requestId, path, type)) {
        FileHandler cb;
        std::string remotePath;
        {
            std::lock_guard lock(mutex_);
            auto it = pendingFileTransfers_.find(requestId);
            if (it != pendingFileTransfers_.end()) {
                remotePath = it->second.first;
                cb = std::move(it->second.second);
                pendingFileTransfers_.erase(it);
            }
        }
        if (cb) {
            FileDataResult result;
            result.success = false;
            result.path = std::move(remotePath);
            result.error = "Remote host not connected";
            cb(std::move(result));
        }
    }
}

void FileOpsClient::UploadFile(const std::string& destinationPath,
                               std::vector<uint8_t> data,
                               UploadHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pendingUploads_[requestId] = std::make_pair(destinationPath, std::move(handler));
    }
    if (!server_.UploadFile(requestId, destinationPath, data)) {
        UploadHandler cb;
        std::string remotePath;
        {
            std::lock_guard lock(mutex_);
            auto it = pendingUploads_.find(requestId);
            if (it != pendingUploads_.end()) {
                remotePath = it->second.first;
                cb = std::move(it->second.second);
                pendingUploads_.erase(it);
            }
        }
        if (cb) {
            UploadResult result;
            result.success = false;
            result.destinationPath = std::move(remotePath);
            result.error = "Remote host not connected";
            cb(std::move(result));
        }
    }
}

void FileOpsClient::HandleResponse(const dialhome::protocol::DirectoryListResponse& response) {
    ResponseHandler handler;
    {
        std::lock_guard lock(mutex_);
        auto it = pending_.find(response.requestId);
        if (it != pending_.end()) {
            handler = std::move(it->second);
            pending_.erase(it);
        }
    }
    if (!handler) {
        return;
    }

    DirectoryResult result;
    result.success = response.success;
    result.path = response.path;
    result.entries = response.entries;
    result.error = response.error;
    handler(std::move(result));
}

void FileOpsClient::HandleFileTransferResponse(const dialhome::protocol::FileTransferResponse& response) {
    FileHandler handler;
    std::string remotePath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingFileTransfers_.find(response.requestId);
        if (it != pendingFileTransfers_.end()) {
            remotePath = it->second.first;
            handler = std::move(it->second.second);
            pendingFileTransfers_.erase(it);
        }
    }
    if (!handler) {
        return;
    }
    FileDataResult result;
    result.success = response.success;
    result.path = std::move(remotePath);
    if (response.success) {
        result.data = response.data;
    }
    result.error = response.error;
    handler(std::move(result));
}

void FileOpsClient::HandleFileUploadResult(const dialhome::protocol::FileUploadResult& resultPacket) {
    UploadHandler handler;
    std::string destinationPath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingUploads_.find(resultPacket.requestId);
        if (it != pendingUploads_.end()) {
            destinationPath = it->second.first;
            handler = std::move(it->second.second);
            pendingUploads_.erase(it);
        }
    }
    if (!handler) {
        return;
    }

    UploadResult result;
    result.success = resultPacket.success;
    result.destinationPath = std::move(destinationPath);
    result.error = resultPacket.error;
    handler(std::move(result));
}
}
