CString FormatFileSize(uintmax_t size) {
    static LPCTSTR kUnits[] = {_T("B"), _T("KB"), _T("MB"), _T("GB"), _T("TB")};
    double value = static_cast<double>(size);
    constexpr size_t kUnitCount = sizeof(kUnits) / sizeof(kUnits[0]);
    size_t index = 0;
    while (value >= 1024.0 && index + 1 < kUnitCount) {
        value /= 1024.0;
        ++index;
    }
    CString formatted;
    if (index == 0) {
        formatted.Format(_T("%llu %s"), static_cast<unsigned long long>(size), kUnits[index]);
    } else {
        formatted.Format(_T("%.2f %s"), value, kUnits[index]);
    }
    return formatted;
}

std::wstring Utf8ToWide(const std::string& value) {
    if (value.empty()) {
        return {};
    }
    int needed = MultiByteToWideChar(CP_UTF8, 0, value.c_str(), static_cast<int>(value.size()), nullptr, 0);
    if (needed <= 0) {
        return {};
    }
    std::wstring result(static_cast<size_t>(needed), L'\0');
    MultiByteToWideChar(CP_UTF8, 0, value.c_str(), static_cast<int>(value.size()), result.data(), needed);
    return result;
}

std::string WideToUtf8(const std::wstring& value) {
    if (value.empty()) {
        return {};
    }
    int needed = WideCharToMultiByte(CP_UTF8, 0, value.c_str(), static_cast<int>(value.size()), nullptr, 0, nullptr, nullptr);
    if (needed <= 0) {
        return {};
    }
    std::string result(static_cast<size_t>(needed), '\0');
    WideCharToMultiByte(CP_UTF8, 0, value.c_str(), static_cast<int>(value.size()), result.data(), needed, nullptr, nullptr);
    return result;
}

std::wstring SanitizeFileName(std::wstring name) {
    static constexpr wchar_t kInvalid[] = L"<>:\"/\\|?*";
    for (auto& ch : name) {
        if (wcschr(kInvalid, ch)) {
            ch = L'_';
        }
    }
    return name;
}

std::string ParentRemotePath(const std::string& path) {
    if (path.empty()) {
        return {};
    }
    std::filesystem::path fs(path);
    auto parent = fs.parent_path();
    if (parent.empty() || parent == fs) {
        return {};
    }
    return parent.string();
}

std::string CombineRemotePath(const std::string& base, const std::string& child) {
    if (base.empty()) {
        return child;
    }
    std::filesystem::path fs(base);
    fs /= child;
    return fs.lexically_normal().string();
}
}

