    38	CString FormatFileSize(uintmax_t size) {
    39	    static LPCTSTR kUnits[] = {_T("B"), _T("KB"), _T("MB"), _T("GB"), _T("TB")};
    40	    double value = static_cast<double>(size);
    41	    constexpr size_t kUnitCount = sizeof(kUnits) / sizeof(kUnits[0]);
    42	    size_t index = 0;
    43	    while (value >= 1024.0 && index + 1 < kUnitCount) {
    44	        value /= 1024.0;
    45	        ++index;
    46	    }
    47	    CString formatted;
    48	    if (index == 0) {
    49	        formatted.Format(_T("%llu %s"), static_cast<unsigned long long>(size), kUnits[index]);
    50	    } else {
    51	        formatted.Format(_T("%.2f %s"), value, kUnits[index]);
    52	    }
    53	    return formatted;
    54	}
