#include "FileOpsClient.h"

#include <random>

namespace dialhome::files {
namespace {
std::filesystem::path MakeTempFilePath() {
    auto tempDir = std::filesystem::temp_directory_path();
    std::random_device rd;
    std::mt19937_64 gen(rd());
    auto token = gen();
    std::filesystem::path candidate;
    do {
        candidate = tempDir / ("dialhome_download_" + std::to_string(token++));
    } while (std::filesystem::exists(candidate));
    return candidate;
}
}

FileOpsClient::FileOpsClient(control::ControlServer& server)
    : server_(server) {
    server_.SetDirectoryResponseCallback(
        [this](const dialhome::protocol::DirectoryListResponse& response) { HandleResponse(response); });
    server_.SetFileTransferResponseCallback(
        [this](const dialhome::protocol::FileTransferResponse& response) { HandleFileTransferResponse(response); });
    server_.SetFileUploadResultCallback(
        [this](const dialhome::protocol::FileUploadResult& result) { HandleFileUploadResult(result); });
}

void FileOpsClient::RequestList(const std::string& path, ResponseHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pending_[requestId] = std::move(handler);
    }

    if (!server_.RequestDirectoryList(requestId, path)) {
        DirectoryResult result;
        result.success = false;
        result.path = path;
        result.error = "Remote host not connected";
        ResponseHandler cb;
        {
            std::lock_guard lock(mutex_);
            auto it = pending_.find(requestId);
            if (it != pending_.end()) {
                cb = std::move(it->second);
                pending_.erase(it);
            }
        }
        if (cb) {
            cb(std::move(result));
        }
    }
}

void FileOpsClient::RequestFile(const std::string& path,
                                protocol::FileTransferType type,
                                const std::filesystem::path& destination,
                                FileHandler handler) {
    if (!handler) {
        return;
    }
    uint32_t requestId;
    std::filesystem::path target = destination;
    if (target.empty()) {
        target = MakeTempFilePath();
    }
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        pendingFileTransfers_[requestId] = DownloadContext{path, target, std::move(handler)};
    }

    if (!server_.RequestFileTransfer(requestId, path, type)) {
        FileHandler cb;
        std::string remotePath;
        std::filesystem::path localPath;
        {
            std::lock_guard lock(mutex_);
            auto it = pendingFileTransfers_.find(requestId);
            if (it != pendingFileTransfers_.end()) {
                remotePath = it->second.remotePath;
                localPath = it->second.destination;
                cb = std::move(it->second.handler);
                pendingFileTransfers_.erase(it);
            }
        }
        if (cb) {
            FileDataResult result;
            result.success = false;
            result.path = std::move(remotePath);
            result.localPath = std::move(localPath);
            result.error = "Remote host not connected";
            cb(std::move(result));
        }
    }
}

void FileOpsClient::UploadFile(const std::string& destinationPath,
                               const std::filesystem::path& localPath,
                               UploadHandler handler) {
    if (!handler) {
        return;
    }
    std::error_code ec;
    auto fileSize = std::filesystem::file_size(localPath, ec);
    if (ec) {
        UploadResult result;
        result.success = false;
        result.destinationPath = destinationPath;
        result.error = "Unable to read local file";
        handler(std::move(result));
        return;
    }

    uint32_t requestId;
    {
        std::lock_guard lock(mutex_);
        requestId = nextRequestId_++;
        UploadContext ctx;
        ctx.remotePath = destinationPath;
        ctx.sourcePath = localPath;
        ctx.handler = std::move(handler);
        ctx.totalBytes = static_cast<uint64_t>(fileSize);
        pendingUploads_[requestId] = std::move(ctx);
    }

    if (!server_.UploadFile(requestId, destinationPath, static_cast<uint64_t>(fileSize))) {
        UploadHandler cb;
        std::string remotePath;
        {
            std::lock_guard lock(mutex_);
            auto it = pendingUploads_.find(requestId);
            if (it != pendingUploads_.end()) {
                remotePath = it->second.remotePath;
                cb = std::move(it->second.handler);
                pendingUploads_.erase(it);
            }
        }
        if (cb) {
            UploadResult result;
            result.success = false;
            result.destinationPath = std::move(remotePath);
            result.error = "Remote host not connected";
            cb(std::move(result));
        }
    }
}

std::optional<std::filesystem::path> FileOpsClient::AcquireDownloadDestination(uint32_t requestId) {
    std::lock_guard lock(mutex_);
    auto it = pendingFileTransfers_.find(requestId);
    if (it == pendingFileTransfers_.end()) {
        return std::nullopt;
    }
    auto& dest = it->second.destination;
    auto parent = dest.parent_path();
    if (!parent.empty() && !std::filesystem::exists(parent)) {
        std::filesystem::create_directories(parent);
    }
    return dest;
}

void FileOpsClient::OnDownloadCompleted(uint32_t requestId,
                                        bool success,
                                        const std::filesystem::path& localPath,
                                        const std::string& error) {
    FileHandler handler;
    std::string remotePath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingFileTransfers_.find(requestId);
        if (it != pendingFileTransfers_.end()) {
            handler = std::move(it->second.handler);
            remotePath = it->second.remotePath;
            pendingFileTransfers_.erase(it);
        }
    }
    if (!handler) {
        return;
    }
    FileDataResult result;
    result.success = success;
    result.path = std::move(remotePath);
    result.localPath = localPath;
    if (!success) {
        result.error = error;
    }
    handler(std::move(result));
}

std::optional<std::filesystem::path> FileOpsClient::AcquireUploadSource(uint32_t requestId) {
    std::lock_guard lock(mutex_);
    auto it = pendingUploads_.find(requestId);
    if (it == pendingUploads_.end()) {
        return std::nullopt;
    }
    return it->second.sourcePath;
}

void FileOpsClient::OnUploadCompleted(uint32_t requestId, bool success, const std::string& error) {
    UploadHandler handler;
    std::string remotePath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingUploads_.find(requestId);
        if (it != pendingUploads_.end()) {
            handler = std::move(it->second.handler);
            remotePath = it->second.remotePath;
            pendingUploads_.erase(it);
        }
    }
    if (!handler) {
        return;
    }
    UploadResult result;
    result.success = success;
    result.destinationPath = std::move(remotePath);
    if (!success) {
        result.error = error;
    }
    handler(std::move(result));
}

void FileOpsClient::HandleResponse(const dialhome::protocol::DirectoryListResponse& response) {
    ResponseHandler handler;
    {
        std::lock_guard lock(mutex_);
        auto it = pending_.find(response.requestId);
        if (it != pending_.end()) {
            handler = std::move(it->second);
            pending_.erase(it);
        }
    }
    if (!handler) {
        return;
    }

    DirectoryResult result;
    result.success = response.success;
    result.path = response.path;
    result.entries = response.entries;
    result.error = response.error;
    handler(std::move(result));
}

void FileOpsClient::HandleFileTransferResponse(const dialhome::protocol::FileTransferResponse& response) {
    bool removeContext = !response.success;
    FileHandler handler;
    std::string remotePath;
    std::filesystem::path localPath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingFileTransfers_.find(response.requestId);
        if (it != pendingFileTransfers_.end()) {
            remotePath = it->second.remotePath;
            localPath = it->second.destination;
            if (removeContext) {
                handler = std::move(it->second.handler);
                pendingFileTransfers_.erase(it);
            }
        }
    }

    if (removeContext && handler) {
        FileDataResult result;
        result.success = false;
        result.path = std::move(remotePath);
        result.localPath = std::move(localPath);
        result.error = response.error;
        handler(std::move(result));
    }
}

void FileOpsClient::HandleFileUploadResult(const dialhome::protocol::FileUploadResult& resultPacket) {
    UploadHandler handler;
    std::string destinationPath;
    {
        std::lock_guard lock(mutex_);
        auto it = pendingUploads_.find(resultPacket.requestId);
        if (it != pendingUploads_.end()) {
            handler = std::move(it->second.handler);
            destinationPath = it->second.remotePath;
            pendingUploads_.erase(it);
        }
    }
    if (!handler) {
        return;
    }

    UploadResult result;
    result.success = resultPacket.success;
    result.destinationPath = std::move(destinationPath);
    result.error = resultPacket.error;
    handler(std::move(result));
}
}
