class FileOpsClient {
public:
    struct DirectoryResult {
        bool success = false;
        std::string path;
        std::vector<dialhome::protocol::DirectoryEntry> entries;
        std::string error;
    };

    struct FileDataResult {
        bool success = false;
        std::string path;
        std::vector<uint8_t> data;
        std::string error;
    };

    struct UploadResult {
        bool success = false;
        std::string destinationPath;
        std::string error;
    };

    using ResponseHandler = std::function<void(DirectoryResult)>;
    using FileHandler = std::function<void(FileDataResult)>;
    using UploadHandler = std::function<void(UploadResult)>;

    explicit FileOpsClient(control::ControlServer& server);

    void RequestList(const std::string& path, ResponseHandler handler);
    void RequestFile(const std::string& path,
                     protocol::FileTransferType type,
                     FileHandler handler);
    void UploadFile(const std::string& destinationPath,
                    std::vector<uint8_t> data,
                    UploadHandler handler);

private:
    void HandleResponse(const dialhome::protocol::DirectoryListResponse& response);
    void HandleFileTransferResponse(const dialhome::protocol::FileTransferResponse& response);
    void HandleFileUploadResult(const dialhome::protocol::FileUploadResult& result);

    control::ControlServer& server_;
    std::mutex mutex_;
    uint32_t nextRequestId_ = 1;
    std::unordered_map<uint32_t, ResponseHandler> pending_;
    std::unordered_map<uint32_t, std::pair<std::string, FileHandler>> pendingFileTransfers_;
    std::unordered_map<uint32_t, std::pair<std::string, UploadHandler>> pendingUploads_;
};
