    list_.InsertColumn(1, _T("Size"), LVCFMT_RIGHT, 120);
    list_.InsertColumn(2, _T("Modified"), LVCFMT_LEFT, 170);

    int buttonTop = rect.Height() - 55;
    CRect buttonRect(rect.Width() / 3 + 20, buttonTop, rect.Width() / 3 + 110, buttonTop + 30);
    openButton_.Create(_T("Open"), WS_CHILD | WS_VISIBLE | BS_PUSHBUTTON, buttonRect, this, IDC_BTN_OPEN);
    buttonRect.OffsetRect(100, 0);
    downloadButton_.Create(_T("Download"), WS_CHILD | WS_VISIBLE | BS_PUSHBUTTON, buttonRect, this, IDC_BTN_DOWNLOAD);
    buttonRect.OffsetRect(110, 0);
    uploadButton_.Create(_T("Upload"), WS_CHILD | WS_VISIBLE | BS_PUSHBUTTON, buttonRect, this, IDC_BTN_UPLOAD);
    UpdateButtons();

    RequestDirectory(std::string{});
    return TRUE;
}

void FileManagerDlg::RequestDirectory(const std::string& path) {
    if (!fileOpsClient_) {
        return;
    }
    fileOpsClient_->RequestList(path, [this](files::FileOpsClient::DirectoryResult result) {
        auto payload = new files::FileOpsClient::DirectoryResult(std::move(result));
        PostMessage(WM_FILEOPS_DIR_RESULT, reinterpret_cast<WPARAM>(payload), 0);
    });
}

void FileManagerDlg::UpdateList(const files::FileOpsClient::DirectoryResult& result) {
    currentPath_ = result.path;
    parentPath_ = ParentRemotePath(currentPath_);
    currentEntries_ = result.entries;
    list_.DeleteAllItems();
    showParentRow_ = !parentPath_.empty();

    if (showParentRow_) {
        int row = list_.InsertItem(0, _T(".."));
        list_.SetItemText(row, 1, _T(""));
        list_.SetItemText(row, 2, _T(""));
        list_.SetItemData(row, kParentRowTag);
    }

    int rowIndex = showParentRow_ ? 1 : 0;
    for (size_t i = 0; i < currentEntries_.size(); ++i) {
        const auto& entry = currentEntries_[i];
        CString name(entry.name.c_str());
        int item = list_.InsertItem(rowIndex++, name);
        CString sizeText;
        if (entry.isDirectory) {
            sizeText = _T("<DIR>");
        } else {
            sizeText = FormatFileSize(entry.size);
        }
        list_.SetItemText(item, 1, sizeText);
        CString modified(entry.modified.c_str());
        list_.SetItemText(item, 2, modified);
        list_.SetItemData(item, static_cast<DWORD_PTR>(i));
    }

    UpdateTree();
    UpdateButtons();

    CString title;
    CString pathText(currentPath_.empty() ? _T(".") : currentPath_.c_str());
    title.Format(_T("Remote Files - %s"), pathText.GetString());
    SetWindowText(title);
}

void FileManagerDlg::UpdateTree() {
    if (!::IsWindow(tree_.GetSafeHwnd())) {
        return;
    }
    tree_.DeleteAllItems();
    CString rootLabel(currentPath_.empty() ? _T(".") : currentPath_.c_str());
    HTREEITEM root = tree_.InsertItem(rootLabel, 0, 0);
    tree_.SetItemData(root, kTreeRootTag);
    if (showParentRow_) {
        HTREEITEM parent = tree_.InsertItem(_T(".."), 0, 0, root);
        tree_.SetItemData(parent, kParentRowTag);
    }
    for (size_t i = 0; i < currentEntries_.size(); ++i) {
        if (!currentEntries_[i].isDirectory) {
            continue;
        }
        CString name(currentEntries_[i].name.c_str());
        HTREEITEM child = tree_.InsertItem(name, 0, 0, root);
        tree_.SetItemData(child, static_cast<DWORD_PTR>(i));
    }
    tree_.Expand(root, TVE_EXPAND);
    tree_.SelectItem(root);
}

void FileManagerDlg::UpdateButtons() {
    auto index = SelectedEntryIndex();
    bool enableFileActions = index.has_value() && !currentEntries_[*index].isDirectory;
    openButton_.EnableWindow(enableFileActions);
    downloadButton_.EnableWindow(enableFileActions);
    uploadButton_.EnableWindow(fileOpsClient_ != nullptr);
}

std::optional<size_t> FileManagerDlg::SelectedEntryIndex() const {
    int item = list_.GetNextItem(-1, LVNI_SELECTED);
    if (item < 0) {
        return std::nullopt;
    }
    auto tag = list_.GetItemData(item);
    if (tag == kParentRowTag) {
        return std::nullopt;
    }
    return static_cast<size_t>(tag);
}

void FileManagerDlg::NavigateTo(const std::string& path) {
    RequestDirectory(path);
}

void FileManagerDlg::NavigateToParent() {
    if (!parentPath_.empty()) {
        NavigateTo(parentPath_);
    }
}

void FileManagerDlg::HandleEntryActivation(size_t index) {
    if (index >= currentEntries_.size()) {
        return;
    }
    const auto& entry = currentEntries_[index];
    if (entry.isDirectory) {
        NavigateTo(BuildChildPath(entry.name));
    } else {
        BeginDownload(entry, dialhome::protocol::FileTransferType::Open, true, std::wstring{});
    }
}

std::string FileManagerDlg::BuildChildPath(const std::string& name) const {
    return CombineRemotePath(currentPath_, name);
}

void FileManagerDlg::BeginDownload(const dialhome::protocol::DirectoryEntry& entry,
                                   dialhome::protocol::FileTransferType type,
                                   bool openAfterDownload,
                                   std::wstring destinationPath) {
    if (!fileOpsClient_) {
        return;
    }
    auto remotePath = BuildChildPath(entry.name);
    fileOpsClient_->RequestFile(remotePath,
                                type,
                                [this, openAfterDownload, destination = std::move(destinationPath), displayName = entry.name](
                                    files::FileOpsClient::FileDataResult result) mutable {
            auto payload = new DownloadPayload{openAfterDownload ? FileAction::Open : FileAction::Save,
                                               std::move(destination),
                                               displayName,
                                               std::move(result)};
            PostMessage(WM_FILEOPS_DOWNLOAD_RESULT, reinterpret_cast<WPARAM>(payload), 0);
        });
}

void FileManagerDlg::BeginUpload(const std::wstring& localPath, const std::wstring& remoteName) {
    if (!fileOpsClient_) {
        return;
    }
    std::ifstream stream(localPath.c_str(), std::ios::binary);
    if (!stream) {
        CString msg;
        msg.Format(_T("Unable to open %s"), localPath.c_str());
        AfxMessageBox(msg, MB_ICONERROR | MB_OK);
        return;
    }
    std::vector<uint8_t> buffer((std::istreambuf_iterator<char>(stream)), std::istreambuf_iterator<char>());
    if (!stream && !stream.eof()) {
        CString msg;
        msg.Format(_T("Failed reading %s"), localPath.c_str());
        AfxMessageBox(msg, MB_ICONERROR | MB_OK);
        return;
    }
    std::string remotePath = CombineRemotePath(currentPath_, WideToUtf8(remoteName));
    fileOpsClient_->UploadFile(remotePath, std::move(buffer), [this](files::FileOpsClient::UploadResult result) {
        auto payload = new UploadPayload{std::move(result)};
        PostMessage(WM_FILEOPS_UPLOAD_RESULT, reinterpret_cast<WPARAM>(payload), 0);
    });
}

bool FileManagerDlg::WriteBytesToFile(const std::filesystem::path& path,
                                       const std::vector<uint8_t>& data,
                                       CString& errorText) {
    std::ofstream stream(path, std::ios::binary | std::ios::trunc);
    if (!stream) {
        errorText.Format(_T("Unable to write %s"), path.c_str());
        return false;
    }
    stream.write(reinterpret_cast<const char*>(data.data()), static_cast<std::streamsize>(data.size()));
    if (!stream) {
        errorText.Format(_T("Failed to write %s"), path.c_str());
        return false;
    }
    return true;
}

std::filesystem::path FileManagerDlg::CreateTempCopyPath(const std::wstring& preferredName) const {
    auto baseName = preferredName.empty() ? std::wstring(L"remote_file.bin") : preferredName;
    baseName = SanitizeFileName(baseName);
    auto temp = std::filesystem::temp_directory_path();
    std::filesystem::path candidate = temp / baseName;
    int suffix = 1;
    while (std::filesystem::exists(candidate)) {
        std::wstring withSuffix = baseName + L" (" + std::to_wstring(suffix++) + L")";
        candidate = temp / withSuffix;
    }
    return candidate;
}

void FileManagerDlg::CleanupTempFiles() {
    for (const auto& temp : tempFiles_) {
        std::error_code ec;
        std::filesystem::remove(temp, ec);
    }
    tempFiles_.clear();
}

LRESULT FileManagerDlg::OnDirectoryResult(WPARAM wParam, LPARAM) {
    std::unique_ptr<files::FileOpsClient::DirectoryResult> payload(
        reinterpret_cast<files::FileOpsClient::DirectoryResult*>(wParam));
    if (!payload) {
        return 0;
    }
    if (!payload->success) {
        CString message(payload->error.c_str());
        if (message.IsEmpty()) {
            message = _T("Unable to retrieve directory listing");
        }
        AfxMessageBox(message, MB_ICONERROR | MB_OK);
        return 0;
    }
    UpdateList(*payload);
    return 0;
}

LRESULT FileManagerDlg::OnDownloadResult(WPARAM wParam, LPARAM) {
    std::unique_ptr<DownloadPayload> payload(reinterpret_cast<DownloadPayload*>(wParam));
    if (!payload) {
        return 0;
    }
    if (!payload->result.success) {
        CString message(payload->result.error.c_str());
        if (message.IsEmpty()) {
            message = _T("Download failed");
        }
        AfxMessageBox(message, MB_ICONERROR | MB_OK);
        return 0;
    }

    std::filesystem::path targetPath;
    if (payload->action == FileAction::Open) {
        std::wstring preferred = Utf8ToWide(payload->result.path);
        targetPath = CreateTempCopyPath(preferred);
    } else {
        targetPath = payload->destination;
    }

    CString errorText;
    if (!WriteBytesToFile(targetPath, payload->result.data, errorText)) {
        AfxMessageBox(errorText, MB_ICONERROR | MB_OK);
        return 0;
    }

    if (payload->action == FileAction::Open) {
        tempFiles_.push_back(targetPath);
        ShellExecuteW(GetSafeHwnd(), L"open", targetPath.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
    } else {
        CString message;
        message.Format(_T("Saved to %s"), targetPath.c_str());
        AfxMessageBox(message, MB_ICONINFORMATION | MB_OK);
    }
    return 0;
}

LRESULT FileManagerDlg::OnUploadResult(WPARAM wParam, LPARAM) {
    std::unique_ptr<UploadPayload> payload(reinterpret_cast<UploadPayload*>(wParam));
    if (!payload) {
        return 0;
    }
    if (!payload->result.success) {
        CString message(payload->result.error.c_str());
        if (message.IsEmpty()) {
            message = _T("Upload failed");
        }
        AfxMessageBox(message, MB_ICONERROR | MB_OK);
        return 0;
    }
    CString destination(Utf8ToWide(payload->result.destinationPath).c_str());
    CString message;
    message.Format(_T("Uploaded to %s"), destination.IsEmpty() ? _T("remote host") : destination.GetString());
    AfxMessageBox(message, MB_ICONINFORMATION | MB_OK);
    RequestDirectory(currentPath_);
    return 0;
}

void FileManagerDlg::OnListDblClick(NMHDR* nmhdr, LRESULT* result) {
    UNREFERENCED_PARAMETER(nmhdr);
    if (result) {
        *result = 0;
    }
    int item = list_.GetNextItem(-1, LVNI_SELECTED);
    if (item < 0) {
        return;
    }
    auto tag = list_.GetItemData(item);
    if (tag == kParentRowTag) {
        NavigateToParent();
        return;
    }
    HandleEntryActivation(static_cast<size_t>(tag));
}

void FileManagerDlg::OnListSelectionChanged(NMHDR* nmhdr, LRESULT* result) {
    UNREFERENCED_PARAMETER(nmhdr);
    if (result) {
        *result = 0;
    }
    UpdateButtons();
}

void FileManagerDlg::OnTreeDblClick(NMHDR* nmhdr, LRESULT* result) {
    UNREFERENCED_PARAMETER(nmhdr);
    if (result) {
        *result = 0;
    }
    HTREEITEM item = tree_.GetSelectedItem();
    if (!item) {
        return;
    }
    auto tag = tree_.GetItemData(item);
    if (tag == kParentRowTag) {
        NavigateToParent();
    } else if (tag != kTreeRootTag) {
        HandleEntryActivation(static_cast<size_t>(tag));
    }
}

void FileManagerDlg::OnOpenClicked() {
    auto index = SelectedEntryIndex();
    if (!index) {
        return;
    }
    BeginDownload(currentEntries_[*index], dialhome::protocol::FileTransferType::Open, true, std::wstring{});
}

void FileManagerDlg::OnDownloadClicked() {
    auto index = SelectedEntryIndex();
    if (!index) {
        return;
    }
    const auto& entry = currentEntries_[*index];
    CString defaultName(entry.name.c_str());
    CFileDialog dlg(FALSE, nullptr, defaultName, OFN_OVERWRITEPROMPT, _T("All Files (*.*)|*.*||"));
    if (dlg.DoModal() != IDOK) {
        return;
    }
    BeginDownload(entry,
                  dialhome::protocol::FileTransferType::Download,
                  false,
                  std::wstring(dlg.GetPathName().GetString()));
}

void FileManagerDlg::OnUploadClicked() {
    CFileDialog dlg(TRUE, nullptr, nullptr, OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST, _T("All Files (*.*)|*.*||"));
    if (dlg.DoModal() != IDOK) {
        return;
    }
    BeginUpload(std::wstring(dlg.GetPathName().GetString()), std::wstring(dlg.GetFileName().GetString()));
}

}
